(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["it"] = {"ui":{"skip":"Vai al contenuto","back":"← Torna ad AI-gile","lang.button":"Lingua: {name}","lang.dialog":"Scegli una lingua","lang.search":"Cerca lingue","lang.none":"Nessuna lingua corrisponde","lang.notYet":"{name} non è ancora tradotto","theme.aria":"Cambia tema: chiaro, scuro o nero","theme.toLight":"Passa al tema chiaro","theme.toDark":"Passa al tema scuro","theme.toBlack":"Passa al tema nero (nero vero, riposante sugli schermi OLED)","words.underline":"Sottolinea queste parole nella pagina","words.underlineHelp":"Passa il mouse o tocca una parola sottolineata a puntini per vedere cosa significa.","words.col.todo":"Le schede scelte per ora: il team parte da queste.","words.col.doing":"Un'IA sta lavorando su questa scheda in questo momento.","words.col.review":"Un'IA ha finito il lavoro; un'altra lo controlla prima che arrivi a te.","words.col.verify":"Si aspetta te: provalo e dì se funziona.","words.col.team":"I tuoi appunti o le tue risposte, in attesa che il team li prenda in carico.","words.col.done":"Finito e accettato.","index.title":"AI-gile: il tuo team di sviluppo AI, su una sola board","index.description":"AI-gile è una board kanban per team di programmazione AI. Lavorano mentre dormi; tu trovi un'unica pila corta di cose da decidere, provare e accettare.","hero.logoAlt":"Icona della board AI-gile","hero.h1.html":"Il tuo team di sviluppo AI, su una sola&nbsp;board.","hero.alpha":"🐣 Pre-alpha chiusa","hero.alphaTitle":"Ancora acerba e incompleta: grazie di provarla!","hero.lede":"Costruiscono mentre dormi. Ti svegli con un'unica pila corta: qualche domanda, qualche cosa da provare, un rombo viola o due. Clic, accetta, e torni al tuo caffè.","dl.windows":"App per Windows","dl.browser":"Usala nel browser","dl.messenger":"📱 Messenger per il tuo telefono","dl.soon":"In arrivo","dl.notify":"🔔 Avvisami quando apre","dl.notifySmall":"Alpha o beta","hero.secondary":"Agile, ma il team non ha mai bisogno del caffè in piedi della riunione. (Le riunioni in piedi le fa lo stesso.)","pitch.h2":"AI-gile in quante parole vuoi","pitch.lede":"Scegli una lunghezza, da una parola a 144. Ogni lunghezza è una descrizione a sé, scritta per quella misura. Trascina il cursore o usa le frecce.","pitch.rangeLabel":"Lunghezza in parole","pitch.dice":"🎲 un'altra versione","pitch.words.one":"{n} parola","pitch.words.other":"{n} parole","pitch.letters.one":"{n} lettera","pitch.letters.other":"{n} lettere","pitch.chars.one":"{n} carattere","pitch.chars.other":"{n} caratteri","count.line.html.one":"{n} card sulla board in questo momento","count.line.html.other":"{n} card sulla board in questo momento","people.humans.html.one":"👥 {n} umano","people.humans.html.other":"👥 {n} umani","people.agents.html.one":"🤖 {n} agente","people.agents.html.other":"🤖 {n} agenti","people.working.html.one":"⚡ {n} al lavoro in questo momento","people.working.html.other":"⚡ {n} al lavoro in questo momento","pre.title":"AI-gile: qui si sta costruendo qualcosa","pre.description":"Qui si sta costruendo qualcosa. Una board dove team di AI costruiscono quello che chiedi, e intanto ti insegnano. Per ora, pre-alpha chiusa tra amici.","pre.h1":"Qui si sta costruendo qualcosa. 🤫","pre.line":"Una board dove team di AI costruiscono quello che chiedi, e intanto ti insegnano. Per ora, pre-alpha chiusa tra amici.","pre.btn":"🔔 Avvisami quando apre","pre.peek":"Dietro il vetro: la board vera, dal vivo. Ogni scheda è una barra colorata.","pre.peekFake":"Dietro il vetro: ecco com'è una board al lavoro.","pre.night":"🌙 Il guardiano notturno è al comando · 😴 l'umano riposa","features.aria":"Cosa fa","f.pile.h":"Una sola pila per te","f.pile.html":"<b>Per te</b> raccoglie tutto ciò che aspetta te, da ogni progetto: domande, cose da provare, compiti che solo una persona può fare. La tua coda dice cosa viene dopo e quanto ci vuole.","f.sleep.h":"Team che lavorano mentre dormi","f.sleep.p":"Ogni progetto ha un lead e un team di agenti AI. Commenta una card e il team si sveglia, fa il lavoro e te lo restituisce con passaggi che anche una persona stanca può seguire.","f.tester.h":"Prima controlla un tester AI","f.tester.p":"Prima che arrivi qualcosa a te, un tester segue i passaggi in una copia dell'app e mostra cosa ha visto, con uno screenshot. Scorri quelli superati e accetta con un clic.","f.proof.h":"Prove, non promesse","f.proof.p":"Ogni consegna mostra cosa è cambiato: i file, il diff, gli screenshot. Niente più apri-ogni-app-per-vedere-se-è-finito.","f.chat.h":"Chatta con i tuoi lead","f.chat.p":"Una barra stile Discord: un'icona per progetto, rombi viola per ciò che ha bisogno di te. Scrivi un'idea a un lead; la trasforma in card e in un piano, con un pulsante ✅ Vai.","f.tidy.h":"Si tiene in ordine da sola","f.tidy.p":"Le card affini si fondono in una, i titoli confusi vengono sistemati e un controllo dei token tiene il codice snello. Meno cose tra cui passare, meno a cui pensare.","f.private.h":"Tua, sul tuo computer","f.private.li1":"La board gira sulla tua macchina e risponde solo a te.","f.private.li2":"I messaggi privati tra persone sono cifrati end-to-end.","f.private.li3":"Nessun account, nessun tracker, nessun cookie.","f.lang.h":"Nella tua lingua","f.lang.p":"Oltre 120 lingue, dall'olandese, al gallese e al giapponese fino al pirata, a Yoda e al klingon, con un cambio rapido all'inglese per il gergo tecnico.","f.service.h":"Da un'idea a un vero servizio","f.service.p":"Hai costruito con l'AI qualcosa che ora le persone usano? Segnalo come servizio e la board ti aiuta a gestirlo bene: controlli di uptime, una pagina di stato pubblica, incidenti con un resoconto, modifiche che richiedono un Vai, backup controllati ogni giorno. L'Aiuto ti spiega ogni passaggio man mano.","msgr.h2":"AI-gile Messenger: il tuo team in tasca","msgr.p1":"Parla con il tuo team IA senza aprire la board. Chatta con i lead dei tuoi progetti e con i tuoi amici, guarda i passaggi di test di una card e rispondi, tutto dal telefono.","msgr.p2":"Per collegarlo, scansiona un codice QR sulla tua board. Prima volta? Una chat demo amichevole ti fa fare un giro.","msgr.when":"Prima Android, poi una versione web per telefoni e iPhone.","msgr.who":"Il lead del tuo progetto","msgr.b1":"La correzione della modalità scura è pronta. Vuoi i passaggi di test?","msgr.b2":"Sì, grazie!","msgr.b3":"1. Apri Impostazioni. 2. Scegli Scuro. Ti sembra a posto?","tl.aria":"Cronologia dalla prima conversazione alla roadmap","tl.h2":"Dalla prima chiacchierata a ciò che verrà","tl.lede":"Date e orari veri, nel tuo fuso orario. Da oggi in poi è il piano, senza date promesse.","tl.today":"Oggi","tl.planned":"previsto","tl.doing":"in corso","tl.cards.one":"{n} card","tl.cards.other":"{n} card","join.h2":"Unisciti","join.lede":"AI-gile lo sta costruendo un barbuto un po' strambo, con l'AuDHD e qualche battaglia con la salute mentale, insieme a un gran numero di agenti pazienti. Per ora è privato, in un'alpha chiusa con gli amici. Vuoi provarlo quando si apre?","join.btn":"Registra il tuo interesse","join.small":"Ti scriveremo una mail, nient'altro","footer.tag":"AI-gile. Niente tracker, niente cookie, niente caffè in piedi.","footer.licence":"Licenza aziendale","footer.status":"Stato","footer.privacy":"Cosa conserviamo","footer.thanks":"Chiamate grazie a ChilledChat","form.sending":"Invio…","form.failed":"Non ha funzionato: riprova più tardi.","form.offline":"Non riesco a raggiungere AI-gile: riprova più tardi.","form.keep":"Lo usiamo solo per risponderti, poi lo cancelliamo. Niente tracker, niente cookie.","form.keepLink":"Cosa conserviamo","interest.title":"AI-gile: avvisami quando apre l'alpha","interest.description":"Lascia la tua email per sapere quando apre l'alpha o la beta chiusa di AI-gile.","interest.h1":"🔔 Avvisami quando apre","interest.lede":"AI-gile è in pre-alpha chiusa. Lascia la tua email e ti scriviamo una sola volta, quando c'è un posto per te.","interest.email":"La tua email","interest.which":"Quale test?","interest.alpha":"Alpha chiusa: presto, ruvida, molti cambiamenti","interest.beta":"Beta: più stabile, più avanti","interest.both":"Una qualsiasi, la prima che arriva","interest.submit":"Mettimi in lista","interest.thanks":"Grazie! Sei in lista.","licence.title":"AI-gile: licenza aziendale","licence.description":"Usi AI-gile nella tua attività? Richiedi una licenza aziendale gratuita.","licence.h1":"📜 Licenza aziendale","licence.lede":"Usi AI-gile al lavoro? Raccontaci chi sei e cosa fai. Se fa del bene, la licenza è gratuita.","licence.company":"Azienda","licence.website":"Sito web","licence.what":"Di cosa ti occupi","licence.how":"Come aiuta il mondo","licence.email":"Email","licence.submit":"Invia richiesta","licence.thanks":"Grazie! Ti rispondiamo via email.","status.title":"Stato di AI-gile","status.h1":"Stato di AI-gile","status.quiet":"Tutto tranquillo","status.intro":"AI-gile funziona in questo momento? Questa pagina controlla il sito, la condivisione delle board, le chiamate e il download ogni 5 minuti.","status.up":"Funziona (ha risposto in {ms} ms)","status.slow":"Non ha risposto all'ultimo controllo, riprovo","status.down":"Non funziona: non ha risposto agli ultimi due controlli","status.svc.web":"Sito web","status.svc.web.offers":"Questo sito: cos'è AI-gile e il modulo di interesse","status.svc.boards":"Condivisione delle board","status.svc.boards.offers":"Board pubbliche, messaggi tra amici e inviti","status.svc.calls":"Chiamate","status.svc.calls.offers":"Voce, video e condivisione schermo in AI-gile","status.svc.download":"Download","status.svc.download.offers":"Il programma di installazione per Windows e i link di invito","status.checking":"Controllo…","status.offline":"Al momento non riesco a raggiungere il servizio di stato (riprovo)","status.updated":"aggiornato {ago}","status.justNow":"proprio ora","status.min":"{n} min fa","status.hours":"{n} h fa","status.days":"{n} g fa","privacy.title":"AI-gile: cosa conserviamo","privacy.h1":"Cosa conserviamo","privacy.lede":"In breve: solo quello che ci mandi, e non a lungo.","privacy.only":"Solo quello che ci mandi: quello che scrivi in un modulo, come la tua email. Nient'altro su di te.","privacy.sealed":"È sigillato, così il nostro server non può leggerlo: nel tuo browser, prima che parta (su un browser più vecchio, nel momento in cui arriva). Solo la nostra board può aprirlo.","privacy.server":"Viene cancellato dal server appena raggiunge la nostra board. Quello che resta lì dopo 30 giorni viene cancellato comunque.","privacy.board":"Lo teniamo sulla nostra board solo finché non ti abbiamo risposto, poi lo cancelliamo anche lì.","privacy.none":"Niente tracker, niente cookie, niente statistiche.","privacy.local":"La lingua e la scelta tra chiaro e scuro restano nel tuo browser. Non ci vengono mai inviate.","privacy.ask":"Vuoi che sparisca prima? Rispondi alla nostra email e diccelo.","live.h2":"Guardalo mentre prende forma, dal vivo","live.caption":"Ogni scheda è nascosta: vedi la forma del lavoro, non le parole.","live.watching.one":"dal vivo: {n} spettatore","live.watching.other":"dal vivo: {n} spettatori","live.last.now":"Ultima scheda spostata proprio ora","live.last.min.one":"Ultima scheda spostata {n} minuto fa","live.last.min.other":"Ultima scheda spostata {n} minuti fa","live.last.hour.one":"Ultima scheda spostata {n} ora fa","live.last.hour.other":"Ultima scheda spostata {n} ore fa","live.last.day.one":"Ultima scheda spostata {n} giorno fa","live.last.day.other":"Ultima scheda spostata {n} giorni fa","live.offline":"La bacheca dal vivo si prende una pausa. Torna presto.","live.cols":"Backlog|Da fare|In corso|Il team controlla|Per te da testare|Per il team|Fatto","footer.models":"AI-gile mette al lavoro dei modelli di IA per te. Quello che dicono e fanno è roba loro, quindi controlla prima di fidarti.","privacy.ai.h":"La parte IA","privacy.ai.models":"AI-gile è la board. Il lavoro lo fanno modelli di IA di altre aziende, come Claude, Codex e Gemini, sui tuoi account.","privacy.ai.check":"Quello che scrivono e fanno viene da loro e può essere sbagliato. Controlla prima di farci affidamento o di pubblicarlo.","privacy.ai.files":"Modificano file ed eseguono comandi nelle cartelle che colleghi. Fai un backup.","privacy.ai.send":"Quello che dai a un modello va all'azienda che lo gestisce, secondo i suoi termini. Valgono i termini e i costi di ciascuna.","privacy.ai.asis":"AI-gile è una prima versione di prova, fornita così com'è."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Delegato."]},{"n":2,"texts":["Kanban robotico.","Agenti, organizzati.","Idee, realizzate."]},{"n":3,"texts":["Kanban per robot.","Le idee diventano funzioni.","Kanban gratuito, con agenti."]},{"n":5,"texts":["Una board kanban gestita da agenti.","Tu scrivi card. Loro costruiscono.","Gratis, locale, testato, un po' buffo."]},{"n":8,"texts":["Una board kanban gratuita dove lavorano agenti AI.","Scrivi un'idea. Gli agenti la costruiscono. Tu accetti.","Agile per un essere umano e tanti robot pazienti."]},{"n":13,"texts":["Una board kanban sul tuo computer, dove gli agenti AI prendono in carico le card.","Scrivi un'idea. Un team di agenti la costruisce. Un tester la controlla prima di te.","Gratis, senza account né tracker: una board, qualche robot e il comando a te."]},{"n":21,"texts":["AI-gile è una board kanban per lavorare con agenti AI che programmano. Loro prendono in carico le card; tu le provi e le accetti.","Ogni progetto ha un lead e un team di agenti AI. Commenta una qualsiasi card e il team si mette al lavoro.","Una board personale e gratuita che gira sul tuo computer. A lavorare sono i robot. A dire di sì sei tu."]},{"n":34,"texts":["Metti le idee su una board. Un team di agenti AI le trasforma in funzioni che funzionano, le testa e te le riporta con i passaggi per provarle. Niente conta come finito finché non lo dici tu.","AI-gile è una board kanban fatta in casa, che Rich ha costruito con un grande aiuto dagli agenti che ora gestisce. È gratuita, gira sul tuo computer e si condivide con gli amici, non si vende.","Immagina una normale board kanban, con colonne dal Backlog a Fatto, solo che le card le prendono in carico agenti AI. Riferiscono i progressi, fanno domande quando sono bloccati e aspettano sempre il tuo via libera."]},{"n":55,"texts":["AI-gile è una board kanban in cui il team è fatto di agenti AI. Ogni progetto ha un lead che pianifica il lavoro e dei collaboratori che lo costruiscono. Quando una funzione è pronta, un tester AI la prova e fa uno screenshot, poi arriva nella tua pila. Accettala, oppure commenta e la rifanno.","È nata come il modo di una persona per tenere d'occhio tante sessioni di programmazione con l'AI insieme, ed è diventata una vera board. Gira sulla tua macchina, non vuole account e non ha tracker. È gratis per gli amici e per i curiosi. È anche incompleta, quindi aspettati qualche spigolo e ogni tanto una sorpresa.","Ecco la versione onesta. Le idee devi averle tu, e i risultati devi controllarli tu. Quello che fa AI-gile è tutto ciò che sta in mezzo: tiene le card in ordine, sveglia l'agente giusto quando commenti, mostra esattamente cosa è cambiato e raccoglie tutto in un'unica pila corta per te."]},{"n":89,"texts":["AI-gile è una board kanban gratuita che fai girare sul tuo computer. Invece delle persone, ogni progetto ha un team di agenti AI: un lead che trasforma le tue idee in card e in un piano, e dei collaboratori che prendono le card in ordine di priorità. Quando qualcosa è costruito, un tester AI segue i passaggi di prova e ti mostra cosa ha visto. Poi aspetta in un'unica pila chiamata Per te. Tu lo accetti, oppure commenti e il team riprova. Niente arriva mai in Fatto senza di te.","Qualche funzione che forse non ti aspetti. Una guardia notturna tiene piena la colonna Da fare mentre dormi, scegliendo card che non richiedono una tua risposta. Un contatore di token mostra quanto hanno usato gli agenti oggi e in questa settimana, e la modalità No Token Mode dice loro di smettere di spendere. Puoi scrivere agli amici, e i messaggi privati sono cifrati end-to-end. La board parla circa 120 lingue, tra cui olandese, fiammingo, pirata e klingon. Niente di tutto questo costa un centesimo, e nessuno cerca di vendertelo.","AI-gile è un piccolo progetto personale, non un'azienda. Rich voleva seguire diversi progetti di programmazione con l'AI senza aprire ogni app per controllarli, così lui e gli agenti hanno costruito una board per farlo, e poi l'hanno usata per costruire il resto di se stessa. È in pre-alpha chiusa, il che significa che funziona, più o meno, per una manciata di amici. Non c'è una pagina dei prezzi, né una newsletter, né un piano di crescita. Se ti sembra utile, puoi chiedere di provarla quando si aprirà un po' di più."]},{"n":144,"texts":["AI-gile è una board kanban per un essere umano e un sacco di agenti AI. Gira sul tuo computer ed è completamente gratuita. Aggiungi dei progetti, e ogni progetto riceve un lead e un piccolo team. Chatti con il lead, un po' come su Discord, e descrivi un'idea; il lead la trasforma in card e in un piano, poi aspetta che premi Vai. Il team lavora le card in ordine di priorità, usando una semplice riga di comando pensata per i modelli linguistici. Prima che qualcosa torni a te, un tester AI segue i passaggi in una copia dell'app e allega uno screenshot. Il lavoro finito arriva nella tua pila con i file modificati e il diff. Tu lo accetti, oppure lasci un commento e il team si sveglia e riprova. Solo tu puoi spostare una card in Fatto.","Una giornata con AI-gile, più o meno. La sera lasci qualche commento: questo pulsante è nel posto sbagliato, quella lista va ordinata, potremmo avere una modalità scura. Vai a letto. Gli agenti leggono i commenti, fanno le modifiche, le testano e te le riconsegnano. Se Da fare si svuota, la guardia notturna la riempie dal backlog con card che non richiedono risposte da parte tua. La mattina trovi un'unica pila corta: un paio di domande e qualche cosa da provare, ognuna con passaggi che una persona assonnata riesce a seguire e uno screenshot che mostra come funziona. Clicchi, accetti quelle buone e rimandi indietro le altre. Un contatore di token mostra quanto è servito, e No Token Mode c'è per le settimane magre. Poi fai colazione, cosa in cui gli agenti non possono ancora aiutarti.","Prima di tutto, cosa AI-gile non è. Non è una startup, non è in vendita e nessuno raccoglie i tuoi dati. È una board gratuita che gira sul tuo computer, senza account, senza tracker e senza cookie. Cos'è invece: un posto ordinato dove vedere tutti i progetti di programmazione con l'AI in una volta, con un team di agenti che lavora le card e te che prendi le decisioni. Fonde le card affini, sistema i titoli confusi e controlla che il codice resti snello. Parla circa 120 lingue, dall'olandese e dal fiammingo al pirata e al klingon. Gli amici possono scriversi in privato e con cifratura. L'hanno costruita Rich e un gran numero di agenti pazienti, soprattutto usandola. È in pre-alpha chiusa, quindi in certi punti è ruvida. Se ti sembra divertente, chiedi con gentilezza e magari entri in anticipo."]}],"quips":{"1":"Una parola. Audace. Forse troppo.","3":"Tre parole. Già più oneste della maggior parte delle pagine di prodotto.","8":"Otto parole. Ancora meno di una riunione in piedi.","21":"Le lunghezze sono story point, a proposito. Ovviamente.","55":"Cinquantacinque parole. Mentre leggevi, due card sono state completate.","144":"Questa è la più lunga. Il 233 non esiste. Gli agenti sono andati a dormire."}},"timeline":{"first-idea.name":"La prima idea","first-idea.line":"La primissima conversazione, quando non esisteva ancora nessun codice.","first-board.name":"La prima board","first-board.line":"Una board che tiene traccia della propria costruzione: card, colonne, trascina e rilascia, progetti.","team-roles.name":"Team e ruoli","team-roles.line":"Profili degli agenti, modelli di team, spazi e chi fa cosa.","install.name":"Installazione e rilasci","install.line":"Uno zip che un amico può installare, aggiornamenti automatici, canali e ripristino.","usage-saver.name":"Risparmio d'uso","usage-saver.line":"Misurare quanto costano le esecuzioni, tenere il codice snello, risparmiare il limite.","friends.name":"Amici e condivisione","friends.line":"Messaggi privati, un relay cifrato, inviti, ruoli e progetti condivisi.","languages.name":"Lingue","languages.line":"Ogni testo dello schermo in un file di lingua, con olandese e fiammingo per primi.","ai-tester.name":"Tester AI","ai-tester.line":"Un tester controlla prima ogni consegna e mostra cosa ha visto.","website.name":"Il sito web","website.line":"aigile.lol, il teaser e questa cronologia.","streaming.name":"Chat e streaming","streaming.line":"Discord, Twitch, OBS, modalità streamer, GIF ed emoji.","no-ai.name":"Edizione senza AI","no-ai.line":"Una board per chi programma senza AI, e board pubbliche.","night-watch.name":"Guardia notturna","night-watch.line":"Un guardiano e uno Scrum Master tengono i team sul pezzo mentre dormi.","p-more.name":"Tutto il resto","p-more.line":"Idee più piccole che aspettano ancora il loro turno.","p-android.name":"Telefono e Android","p-android.line":"Raggiungi la tua board dal telefono, poi con un'app Android nativa.","p-release.name":"Alpha e oltre","p-release.line":"Alpha chiusa, il sito online, poi la beta.","p-languages.name":"Più lingue","p-languages.line":"130 lingue, e una modalità immersione per chi impara.","p-engines.name":"Più motori AI","p-engines.line":"Scegli Claude, Codex, Gemini, Copilot o Cursor per ogni agente.","p-pro.name":"Pratica professionale","p-pro.line":"Etichette di rischio, blocchi di merge, card di incidente e protezioni.","p-self.name":"Prendersi cura di te","p-self.line":"Modalità stanco, promemoria di cura di sé e le 4:20.","p-servers.name":"Server e crescita","p-servers.line":"Impostazioni globali dei server, ruoli e pianificazione della crescita.","p-livestream.name":"Extra per lo streaming","p-livestream.line":"Chat di Twitch, emoji personalizzate e una vista live pubblica."},"words":{"button":"📖 Gergo tecnico","h":"📖 Parole spiegate","intro":"Formazione gratuita in parole semplici: ogni termine che incontri, dalla prima idea a un servizio su cui la gente conta, passando per l'Agile, lo sviluppo, la sicurezza e il lavoro con l'IA.","search":"Cerca una parola…","none":"Nessuna parola corrisponde.","close":"Chiudi","count":{"one":"{count} parola","other":"{count} parole"},"groups":[{"id":"idea","name":"💡 Idea e scoperta"},{"id":"plan","name":"🗺️ Pianificare il lavoro"},{"id":"agile","name":"🔁 Modi di lavorare agili"},{"id":"build","name":"🛠️ Costruire"},{"id":"test","name":"🧪 Test e qualità"},{"id":"change","name":"🔀 Cambiare in sicurezza"},{"id":"run","name":"🛎️ Gestire un servizio"},{"id":"sec","name":"🔒 Sicurezza e privacy"},{"id":"ai","name":"🤖 Lavorare con l'IA"},{"id":"money","name":"💰 Soldi e licenze"}],"list":[{"id":"discovery","g":"idea","word":"Scoperta (discovery)","text":"La fase iniziale in cui si capisce quale problema vale la pena risolvere e per chi, prima di costruire qualsiasi cosa.","also":["fase di scoperta","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Definizione del problema","text":"Una o due frasi che dicono chi ha un problema, qual è e perché è importante, così tutti puntano nella stessa direzione.","also":["definizioni del problema","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Utente","text":"Una persona che usa ciò che costruisci. Il lavoro si fa per i suoi bisogni.","also":["utenti","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder (parte interessata)","text":"Chiunque tenga a come va a finire il lavoro o ne sia coinvolto, come chi lo paga, lo usa o lo mantiene.","also":["stakeholder","parti interessate","portatori di interesse","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Una persona inventata ma realistica che rappresenta un tipo di utente, così il team può chiedersi «Sam lo troverebbe facile?»","also":["personas","persone tipo"]},{"id":"userresearch","g":"idea","word":"Ricerca sugli utenti","text":"Parlare con persone vere e osservarle per capire di cosa hanno bisogno, invece di tirare a indovinare.","also":["interviste agli utenti","user research","user interviews"]},{"id":"journey","g":"idea","word":"Percorso dell'utente (user journey)","text":"I passi che una persona compie per ottenere qualcosa, da quando ne sente parlare fino alla fine, anche fuori dal tuo prodotto. Disegnarlo mostra dove si blocca.","also":["percorsi dell'utente","customer journey","percorso del cliente","user journey","user journeys"]},{"id":"painpoint","g":"idea","word":"Punto dolente (pain point)","text":"Qualcosa che oggi infastidisce o rallenta le persone. I buoni prodotti tolgono i punti dolenti.","also":["punti dolenti","pain point","pain points","problema ricorrente"]},{"id":"assumption","g":"idea","word":"Assunzione","text":"Qualcosa in cui credi ma che non hai ancora verificato. Mettere per iscritto le assunzioni mostra cosa testare per primo.","also":["assunzioni","presupposto","presupposti","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Ipotesi","text":"Una supposizione ragionata da verificare, con ciò che ti aspetti che succeda, come «le persone si iscriveranno se il primo mese è gratis».","also":["ipotesi","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Esperimento","text":"Un piccolo test pianificato per capire se un'idea funziona, prima di scommetterci molto.","also":["esperimenti","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Prova di fattibilità (PoC)","text":"Un tentativo rapido e grezzo per vedere se un'idea può funzionare. Di solito si butta via una volta ottenuta la risposta.","also":["PoC","POC","proof of concept","proof-of-concept","prova di concetto"]},{"id":"prototype","g":"idea","word":"Prototipo","text":"Un primo modello del prodotto, spesso immagini su cui si può cliccare, per provare l'idea con persone vere prima di costruirla sul serio.","also":["prototipi","prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe (schema della schermata)","text":"Uno schizzo semplice di una schermata che mostra dove vanno le cose, senza colori né contenuti veri.","also":["wireframes","schema della schermata","bozza della schermata"]},{"id":"mockup","g":"idea","word":"Mockup (bozza grafica)","text":"Un'immagine dettagliata di come sarà una schermata, con colori e testi veri, ma dove ancora niente funziona.","also":["mockups","mock-up","mock-ups","bozza grafica"]},{"id":"bizcase","g":"idea","word":"Business case (analisi di convenienza)","text":"Le ragioni per fare un progetto: quanto costa, cosa porta o fa risparmiare, e i rischi.","also":["business cases","analisi di convenienza","caso aziendale"]},{"id":"feasibility","g":"idea","word":"Fattibilità","text":"Se una cosa si può davvero costruire e mantenere con il tempo, i soldi e le competenze che hai.","also":["fattibile","feasibility"]},{"id":"outcome","g":"idea","word":"Risultato (outcome)","text":"Il cambiamento che vuoi per le persone, come meno appuntamenti saltati. Conta più di quante cose costruisci.","also":["risultati","esito","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Prodotto del lavoro (output)","text":"Qualcosa che il team realizza, come una nuova schermata o un report. Realizzarlo non significa automaticamente che aiuti qualcuno.","also":["output","produzione","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Metrica di successo","text":"Un numero che dice se il lavoro ha fatto ciò per cui era nato, come più persone che completano l'ordine.","also":["metriche di successo","indicatore di successo","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Indicatore chiave di prestazione (KPI)","text":"Un numero importante che tieni d'occhio per vedere se le cose vanno bene, come le iscrizioni alla settimana.","also":["KPI","KPIs","indicatore chiave di prestazione","key performance indicator"]},{"id":"okr","g":"idea","word":"Obiettivi e risultati chiave (OKR)","text":"Un modo di fissare i traguardi: l'obiettivo dice cosa vuoi, e alcuni risultati chiave sono i numeri che mostrano che l'hai raggiunto.","also":["OKR","OKRs","obiettivi e risultati chiave"]},{"id":"product","g":"plan","word":"Prodotto","text":"La cosa che viene costruita e mantenuta per i suoi utenti, come un'app, un sito web o uno strumento.","also":["prodotti","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Visione del prodotto","text":"Una breve frase che dice a chi è utile il prodotto e dove è diretto nel lungo periodo.","also":["dichiarazione di visione","product vision","vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"La persona che decide cosa viene costruito e in che ordine, così il team lavora sempre su ciò che conta di più. In AI-gile sei tu.","also":["PO","product owners","responsabile del prodotto","proprietario del prodotto"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"La persona che cura la direzione di un prodotto: quali problemi risolve, per chi e perché. PM può anche voler dire project manager, quindi chiedi quale dei due si intende.","also":["PM","product managers","responsabile di prodotto"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"La persona che tiene un progetto nei tempi e nel budget, seguendo chi fa cosa e per quando.","also":["project managers","capo progetto","responsabile di progetto"]},{"id":"roadmap","g":"plan","word":"Roadmap (piano di percorso)","text":"Un piano di massima di ciò che arriva nei prossimi mesi, in ordine. Mostra la direzione, non date esatte, e cambia man mano che impari.","also":["roadmaps","tabella di marcia","piano di percorso"]},{"id":"milestone","g":"plan","word":"Traguardo (milestone)","text":"Un punto di un progetto che vale la pena segnare, come «prima versione online» o «100 utenti».","also":["traguardi","milestone","milestones","pietra miliare"]},{"id":"mvp","g":"plan","word":"Prodotto minimo funzionante (MVP)","text":"La versione più piccola di un prodotto che è comunque utile a persone vere, così da imparare da loro presto.","also":["MVP","MVPs","minimum viable product","prodotto minimo vitale"]},{"id":"requirement","g":"plan","word":"Requisito","text":"Qualcosa che il prodotto finito deve fare o essere.","also":["requisiti","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Ambito (scope)","text":"Ciò che è incluso nel lavoro e, altrettanto importante, ciò che non lo è.","also":["scope","nell'ambito","fuori ambito","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Dilatazione dell'ambito (scope creep)","text":"Quando al lavoro si aggiungono sempre più cose, poco alla volta, senza che nessuno si accordi sul tempo o sul costo in più, e così non finisce mai davvero.","also":["scope creep","feature creep","dilatazione del progetto"]},{"id":"feature","g":"plan","word":"Funzionalità","text":"Una cosa che il prodotto permette di fare, come «reimpostare la password».","also":["funzionalità","funzione","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic (grande funzionalità)","text":"Un grosso pezzo di lavoro, troppo grande per farlo tutto in una volta, quindi diviso in card più piccole.","also":["epics","epic","grande funzionalità"]},{"id":"story","g":"plan","word":"User story (storia utente)","text":"Un piccolo pezzo di lavoro scritto dal punto di vista dell'utente: «Come cliente, voglio salvare il mio carrello, per finire più tardi.» Avvia la conversazione su cosa costruire.","also":["user stories","storia utente","storie utente","story","stories"]},{"id":"ac","g":"plan","word":"Criteri di accettazione (AC)","text":"I controlli che una card deve superare per contare come finita, concordati prima di iniziare, come «il carrello c'è ancora dopo che esco e rientro».","also":["AC","criteri di accettazione","acceptance criteria"]},{"id":"task","g":"plan","word":"Attività (task)","text":"Un singolo lavoro da fare, spesso un piccolo passo di una storia più grande.","also":["task","attività","compito","compiti","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Un altro nome per una card: un pezzo di lavoro o una richiesta, seguito dall'inizio alla fine.","also":["tickets","segnalazione"]},{"id":"priority","g":"plan","word":"Priorità","text":"Quanto una cosa è importante o urgente rispetto al resto, così il lavoro più importante va per primo.","also":["priorità","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Definizione delle priorità","text":"Mettere il lavoro in ordine di importanza. Un metodo comune è MoSCoW: da fare per forza, da fare se possibile, che si potrebbe fare, che stavolta non si farà.","also":["dare priorità","prioritizzare","prioritization","MoSCoW"]},{"id":"estimate","g":"plan","word":"Stima","text":"La migliore ipotesi possibile su quanto è grande o quanto dura un lavoro. È un'ipotesi, non una promessa.","also":["stime","stimare","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story point (punti di complessità)","text":"Un modo di stimare la dimensione del lavoro confrontando le card tra loro («grande circa il doppio di quella») invece che in ore. Non servono a confrontare i team.","also":["story points","story point","punti di complessità","punti storia"]},{"id":"tshirt","g":"plan","word":"Taglie da maglietta (T-shirt sizing)","text":"Stimare la dimensione del lavoro come S, M, L o XL. Rapido e sufficiente per una prima pianificazione.","also":["t-shirt sizing","t-shirt sizes","taglie t-shirt"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Un gioco per stimare: tutti mostrano insieme una carta con una taglia, poi chi ha dato la stima più alta e chi la più bassa spiegano perché.","also":["Scrum poker","poker della pianificazione"]},{"id":"dependency","g":"plan","word":"Dipendenza","text":"Quando un lavoro non può iniziare o finire finché non lo fa un altro.","also":["dipendenze","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Blocco","text":"Qualsiasi cosa impedisca al lavoro di andare avanti adesso, come una risposta che manca o uno strumento rotto.","also":["blocchi","bloccante","impedimento","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Scadenza","text":"La data entro cui qualcosa deve essere finito.","also":["scadenze","termine","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Consegna (deliverable)","text":"Qualcosa di concreto che il lavoro produce e consegna, come una pagina funzionante o un report.","also":["deliverable","deliverables","consegne","risultato consegnabile"]},{"id":"forecast","g":"plan","word":"Previsione","text":"Una previsione di ciò che probabilmente accadrà, come quando il lavoro sarà finito, in base a ciò che sai finora.","also":["previsioni","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metrica","text":"Qualsiasi cosa misuri e segua nel tempo, come le visite a una pagina o quanto tempo serve per correggere un problema.","also":["metriche","indicatore","metric","metrics"]},{"id":"feedback","g":"plan","word":"Feedback (riscontro)","text":"Ciò che le persone ti dicono del tuo lavoro, nel bene e nel male. Averlo presto e spesso è il cuore dell'Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"L'elenco d'attesa di idee e lavoro non ancora pianificati, con il più importante in cima. Su ciò che c'è lì non si lavora finché non passa in Da fare."},{"id":"sprint","g":"agile","word":"Sprint","text":"Un periodo di lavoro breve e di durata fissa (spesso una o due settimane, mai più di un mese) con un obiettivo e un insieme concordato di card da finire.","also":["sprint"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Un rapido punto quotidiano: cosa ha fatto ogni membro del team, cosa farà dopo e cosa lo blocca. In Scrum si chiama daily scrum.","also":["daily","daily scrum","riunione quotidiana","stand-up","standup","stand-ups","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Un modo di lavorare in cui le card si spostano tra le colonne di una board (come Da fare, In corso, Fatto) e il team limita quanto c'è in corso allo stesso tempo, così il lavoro continua a scorrere."},{"id":"wip","g":"agile","word":"Limite WIP","text":"WIP è l'abbreviazione di «work in progress» (lavoro in corso). Un limite WIP è il numero massimo di card che una colonna dovrebbe contenere alla volta, così il team finisce le cose prima di cominciarne altre.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"La breve checklist del team su cosa vuol dire «finito», per esempio testato e spiegato, prima che una card ti venga consegnata. La sua gemella, la Definition of Ready, dice quando una card è abbastanza chiara per iniziare.","also":["Definition of Done","Definition of Ready","definizione di finito","definizione di pronto","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retrospettiva","text":"Uno sguardo regolare indietro su come lavora il team, per accordarsi su una o due cose da fare meglio la volta dopo. Abbreviazione di retrospettiva. In AI-gile una retro propone un cambiamento nel modo di lavorare del team, e tu dici Via o Non ancora.","also":["retrospettive","retro"]},{"id":"swarm","g":"agile","word":"Sciame","text":"Tutti all'opera: molte persone lasciano l'altro lavoro per sistemare insieme una cosa urgente finché non è risolta. In AI-gile tutti i team aiutano su un solo progetto, e gli altri progetti aspettano nel frattempo.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"In Scrum, la persona che aiuta il team a lavorare bene: toglie ciò che lo blocca, tiene le riunioni sui binari e incoraggia le buone abitudini, senza comandare nessuno. In AI-gile il Lead Scrum Master individua le card bloccate, sollecita i team e ti ricorda cosa è in attesa, su tutti i progetti.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Un modo di lavorare a piccoli passi: costruisci un po', mostri spesso risultati veri, impari da ciò che dicono le persone e cambi il piano strada facendo, invece di pianificare tutto in anticipo.","also":["metodi agili","sviluppo agile","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Manifesto Agile","text":"Un breve testo scritto nel 2001 da persone che fanno software. Mette le persone, i risultati funzionanti, la collaborazione stretta con i clienti e la capacità di adattarsi al cambiamento prima dei piani pesanti e della burocrazia.","also":["Manifesto per lo sviluppo agile del software","Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Modello a cascata (Waterfall)","text":"Il modo di lavorare più vecchio: pianificare tutto, poi costruire tutto, poi testare tutto, una fase dopo l'altra. I cambiamenti tardivi sono difficili e costosi.","also":["Waterfall","cascata","modello a cascata","waterfall model"]},{"id":"iteration","g":"agile","word":"Iterazione","text":"Un ciclo in cui si costruisce qualcosa, lo si controlla e lo si migliora. Il lavoro Agile è una catena di questi cicli, e lo sprint è uno di essi.","also":["iterazioni","iteration","iterations"]},{"id":"increment","g":"agile","word":"Incremento","text":"Un nuovo pezzo funzionante aggiunto al prodotto in uno sprint o in un giro di lavoro, che si integra con ciò che c'era già.","also":["incrementi","increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Un modo di lavorare Agile molto diffuso: un piccolo team lavora in sprint brevi verso un obiettivo, con ruoli precisi e poche riunioni regolari per pianificare, controllare e migliorare."},{"id":"scrumteam","g":"agile","word":"Team Scrum","text":"Il piccolo gruppo che fa il lavoro in Scrum: un product owner, uno Scrum Master e gli sviluppatori.","also":["team Scrum","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Eventi Scrum","text":"Le riunioni regolari in Scrum: la pianificazione dello sprint, il daily scrum, la revisione dello sprint e la retro. Molti le chiamano cerimonie.","also":["cerimonie","cerimonie Scrum","Scrum events","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Pianificazione dello sprint","text":"La riunione all'inizio di uno sprint in cui il team concorda perché lo sprint è importante, quali card prendere e come cominciare.","also":["riunione di pianificazione","sprint planning","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Obiettivo dello sprint","text":"Una frase che dice a cosa serve uno sprint. I compiti piccoli possono cambiare strada facendo, purché l'obiettivo sia raggiunto.","also":["obiettivi dello sprint","sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Backlog dello sprint","text":"Le card scelte per lo sprint in corso, con il piano del team per portarle a termine.","also":["backlog dello sprint","sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Backlog del prodotto","text":"L'elenco completo e ordinato di tutto ciò che potrebbe essere costruito per il prodotto, con il più importante in cima. Cambia di continuo man mano che impari.","also":["backlog di prodotto","product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Obiettivo del prodotto","text":"Il risultato più ampio verso cui va il prodotto, che aiuta il team a scegliere cosa fare dopo.","also":["obiettivi del prodotto","product goal","product goals"]},{"id":"refinement","g":"agile","word":"Raffinamento del backlog (refinement)","text":"Rivedere regolarmente il backlog per sistemare, dividere, ordinare e dettagliare le card, così sono pronte da prendere in carico. Si dice anche backlog grooming.","also":["grooming","backlog grooming","refinement","pulizia del backlog"]},{"id":"sprintreview","g":"agile","word":"Revisione dello sprint","text":"Una riunione alla fine di uno sprint in cui il team mostra ciò che ha finito e ascolta cosa ne pensano le persone, per decidere cosa fare dopo.","also":["revisioni dello sprint","sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Mostrare dal vivo il lavoro finito che funziona, alle persone che l'hanno chiesto.","also":["demos","dimostrazione","dimostrazioni"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox (tempo fissato)","text":"Una quantità di tempo fissa per qualcosa. Quando finisce ti fermi, anche se non è tutto fatto.","also":["timeboxes","timeboxed","tempo limitato","tempo fissato"]},{"id":"velocity","g":"agile","word":"Velocità del team (velocity)","text":"Quanto lavoro un team di solito finisce in uno sprint, usato per capire quanto prenderne la volta dopo. Non è un voto su quanto si impegnano le persone.","also":["velocity","velocità","team velocity"]},{"id":"capacity","g":"agile","word":"Capacità","text":"Quanto lavoro il team può prendere in un periodo, tolte le ferie e gli altri impegni.","noTip":1},{"id":"burndown","g":"agile","word":"Grafico burndown","text":"Un grafico del lavoro rimanente in uno sprint, che scende giorno dopo giorno. Se la linea resta piatta, qualcosa è bloccato.","also":["burndown","burn-down chart","grafico di avanzamento","burndown chart"]},{"id":"burnup","g":"agile","word":"Grafico burnup","text":"Un grafico del lavoro finito che sale nel tempo, accanto al totale previsto, per vedere quando ci arriverai.","also":["burnup","burn-up chart","grafico di crescita","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Board Kanban","text":"La board stessa: una colonna per ogni fase del lavoro, con le card che si spostano da una all'altra.","also":["lavagna Kanban","Kanban board","Kanban boards","bacheca Kanban"]},{"id":"pullsys","g":"agile","word":"Sistema pull (a trazione)","text":"Un modo di lavorare in cui un nuovo lavoro parte solo quando qualcuno ha spazio per prenderlo, invece di essere spinto addosso a chi ha già il piatto pieno.","also":["pull system","pull-based","sistema a trazione"]},{"id":"flow","g":"agile","word":"Flusso","text":"Con quanta fluidità il lavoro avanza sulla board. Un buon flusso significa che le card continuano ad andare avanti invece di accumularsi.","also":["flusso di lavoro","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time (tempo di consegna)","text":"Quanto tempo passa da quando qualcuno chiede una cosa a quando è finita.","also":["lead times","tempo di consegna","tempo totale"]},{"id":"cycletime","g":"agile","word":"Cycle time (tempo di ciclo)","text":"Quanto tempo ci mette una card da quando si inizia davvero a lavorarci a quando è finita.","also":["cycle times","tempo di ciclo","tempo di lavorazione","cycle time"]},{"id":"throughput","g":"agile","word":"Throughput (ritmo di completamento)","text":"Quante card vengono finite in una settimana, o in qualsiasi periodo stabilito.","also":["throughput rate","ritmo di completamento","produttività"]},{"id":"bottleneck","g":"agile","word":"Collo di bottiglia","text":"L'unica fase in cui il lavoro si accumula e rallenta tutto il resto, come lo stretto collo di una bottiglia.","also":["colli di bottiglia","bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Corsia (swimlane)","text":"Una riga che attraversa la board e raggruppa card di un tipo, come il lavoro urgente o le card di un team.","also":["corsie","swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Un modo di lavorare che elimina gli sprechi (tutto ciò che non aiuta il cliente) e tiene il lavoro in movimento."},{"id":"waste","g":"agile","word":"Spreco","text":"In Lean, tutto ciò che richiede fatica ma non aiuta il cliente, come l'attesa, il rifare le cose o costruire cose che nessuno usa.","noTip":1},{"id":"kaizen","g":"agile","word":"Miglioramento continuo","text":"Migliorare un po' alla volta, di continuo, con piccoli cambiamenti regolari, e poi controllare che abbiano aiutato. Le retro sono un modo per farlo. Si dice anche kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Team auto-organizzato","text":"Un team che decide da solo come fare il lavoro, invece di ricevere istruzioni passo passo.","also":["auto-organizzazione","team autogestito","self-organising","self-organising team","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Team multidisciplinare","text":"Un team che ha tutte le competenze necessarie per finire il lavoro da solo, come progettazione, realizzazione e test.","also":["team interfunzionale","cross-functional","cross-functional team","team trasversale"]},{"id":"spike","g":"agile","word":"Spike (indagine)","text":"Una breve ricerca a tempo limitato per rispondere a una domanda prima di impegnarsi nel lavoro vero.","also":["spikes","indagine tecnica"]},{"id":"rework","g":"agile","word":"Rifacimento (rework)","text":"Rifare un lavoro perché la prima volta non era fatto bene.","also":["rework","rifare","rilavorazione","reworked"]},{"id":"safe","g":"agile","word":"Agile su larga scala (SAFe)","text":"Modi di usare l'Agile in tanti team di una grande organizzazione. SAFe (Scaled Agile Framework) è un esempio molto noto.","also":["scaled Agile","Scaled Agile","Agile scalato"]},{"id":"repo","g":"build","word":"Repo","text":"La cartella di codice del progetto con tutta la sua cronologia di commit. Può stare sul tuo computer, su GitHub, o su entrambi.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Una linea di lavoro separata nel codice, così si possono fare modifiche senza toccare la versione principale.","also":["Branch"]},{"id":"commit","g":"build","word":"Commit","text":"Un'istantanea salvata del codice, con una breve nota su cosa è cambiato. Puoi sempre tornare a una di esse.","also":["commit"]},{"id":"push","g":"build","word":"Push","text":"Inviare le tue istantanee salvate (commit) da questo computer alla copia condivisa online, come GitHub, così sono al sicuro e gli altri possono scaricarle."},{"id":"merge","g":"build","word":"Merge","text":"Unire le modifiche di un branch in un altro, di solito di nuovo nella versione principale."},{"id":"pr","g":"build","word":"Pull request","text":"Chiedere che le modifiche di un branch vengano controllate e unite nella versione principale. Alcuni siti la chiamano merge request.","also":["PR","PRs","merge request","richiesta di unione","richiesta di pull"]},{"id":"refactor","g":"build","word":"Refactoring","text":"Riordinare il codice senza cambiare ciò che fa: file più piccoli, nomi più chiari, meno ripetizioni."},{"id":"bug","g":"build","word":"Bug","text":"Qualcosa che non funziona come dovrebbe.","also":["Bug"]},{"id":"peerreview","g":"build","word":"Revisione tra pari","text":"Un secondo paio d'occhi: qualcuno diverso dall'autore controlla il lavoro prima che arrivi a te, così passano meno errori. In AI-gile un'altra IA controlla ogni card.","also":["peer review","code review","revisione del codice"]},{"id":"code","g":"build","word":"Codice","text":"Le istruzioni scritte che dicono a un computer cosa fare. Si dice anche codice sorgente.","also":["codice sorgente","source code","code"],"noTip":1},{"id":"proglang","g":"build","word":"Linguaggio di programmazione","text":"Un linguaggio per scrivere codice, come JavaScript, Python o Java. Ognuno è adatto a lavori diversi.","also":["linguaggi di programmazione","programming language","programming languages"]},{"id":"developer","g":"build","word":"Sviluppatore (dev)","text":"Qualcuno che scrive e modifica il codice. Si dice anche programmatore o ingegnere del software.","also":["sviluppatrice","sviluppatori","programmatore","programmatrice","ingegnere del software","dev","developer","developers","programmer","software engineer"]},{"id":"software","g":"build","word":"Software","text":"I programmi che girano su computer e telefoni, in contrapposizione alle macchine stesse (l'hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Abbreviazione di applicazione: un programma che le persone usano per fare qualcosa, su un telefono, un computer o nel browser.","also":["apps","applicazione","applicazioni","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"App web","text":"Un'app che gira in un browser, quindi non c'è niente da installare.","also":["app web","web app","web apps","applicazione web","web application"]},{"id":"frontend","g":"build","word":"Front end (parte visibile)","text":"La parte di un'app che vedi e su cui clicchi: le schermate, i pulsanti e le parole, spesso nel tuo browser.","also":["front-end","frontend","lato client"]},{"id":"backend","g":"build","word":"Back end (dietro le quinte)","text":"La parte di un'app che lavora dietro le quinte, tiene i dati e fa il lavoro quando clicchi qualcosa, come controllare la tua password.","also":["back-end","backend","lato server"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Lavorare sia sul front end sia sul back end.","also":["full-stack","fullstack"]},{"id":"ui","g":"build","word":"Interfaccia utente (UI)","text":"Ciò che una persona vede e usa sullo schermo: disposizione, pulsanti, menu e testi.","also":["UI","interfaccia","user interface"]},{"id":"ux","g":"build","word":"Esperienza utente (UX)","text":"Com'è usare qualcosa: facile, chiaro e piacevole, oppure confuso e lento.","also":["UX","esperienza d'uso","user experience"]},{"id":"accessibility","g":"build","word":"Accessibilità (a11y)","text":"Fare in modo che tutti possano usare le cose, comprese le persone che vedono male, non possono usare il mouse o usano uno screen reader.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Design responsive","text":"Fare in modo che le pagine si adattino e funzionino bene su qualsiasi dimensione di schermo, dal telefono al grande monitor.","also":["responsive design","design reattivo","design adattivo"]},{"id":"designsys","g":"build","word":"Design system","text":"Un kit condiviso di colori, caratteri, pulsanti e regole, così ogni schermata ha lo stesso aspetto e lo stesso comportamento.","also":["design systems","sistema di design"]},{"id":"architecture","g":"build","word":"Architettura","text":"La forma generale di un sistema: quali sono le parti principali e come si parlano."},{"id":"database","g":"build","word":"Database (DB)","text":"Un archivio organizzato di informazioni, come un foglio di calcolo molto potente che l'app può leggere e modificare.","also":["banca dati","basi di dati","database","databases","DB"]},{"id":"schema","g":"build","word":"Schema del database","text":"L'organizzazione di un database: quali tabelle di informazioni ha e cosa contiene ciascuna.","also":["schema","schema del DB"]},{"id":"sql","g":"build","word":"SQL","text":"Abbreviazione di «linguaggio di interrogazione strutturato»: il linguaggio usato per chiedere informazioni a molti database o per modificarle.","also":["linguaggio di interrogazione strutturato","Structured Query Language"]},{"id":"data","g":"build","word":"Dati","text":"Le informazioni conservate da un computer, come nomi, ordini o impostazioni.","also":["dato","insieme di dati","dataset","datasets","data"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Un computer sempre acceso che risponde alle richieste di altri computer, come mandarti una pagina web quando la visiti.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"Chi chiede qualcosa, di solito il tuo browser o la tua app, rivolgendosi a un server. In ambito commerciale vuol dire anche semplicemente cliente.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Abbreviazione di application programming interface (interfaccia di programmazione): un menu fisso di richieste che un programma può fare a un altro, come chiedere a un servizio meteo le previsioni di oggi.","also":["APIs","interfaccia di programmazione","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint (punto di accesso)","text":"Una voce del menu di un'API: un indirizzo web che un programma può chiamare per ottenere o inviare qualcosa.","also":["endpoints","punto di accesso","punto finale"]},{"id":"integration","g":"build","word":"Integrazione","text":"Collegare due sistemi perché lavorino insieme, come il tuo negozio che manda gli ordini al programma di contabilità.","also":["integrazioni","collegamento","integration","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Un messaggio che un sistema manda da solo a un altro nel momento in cui succede qualcosa, come «pagamento ricevuto».","also":["webhooks"]},{"id":"library","g":"build","word":"Libreria (library)","text":"Codice già pronto scritto da qualcun altro, che puoi riusare invece di scriverlo tu.","also":["librerie","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework (struttura di base)","text":"Una struttura già pronta per costruire un'app, che decide gran parte di come è organizzato il codice, come l'ossatura di una casa che tu riempi.","also":["frameworks","struttura di base","ossatura"]},{"id":"sdk","g":"build","word":"Kit di sviluppo (SDK)","text":"Una scatola di strumenti, codice ed esempi per creare software per una piattaforma o un servizio.","also":["SDK","SDKs","software development kit"]},{"id":"softdep","g":"build","word":"Dipendenza software","text":"Una libreria o uno strumento di cui il tuo codice ha bisogno per funzionare. Tenerli aggiornati è importante per la sicurezza.","also":["dipendenze software","software dependency","software dependencies"]},{"id":"package","g":"build","word":"Pacchetto (package)","text":"Un insieme di codice già pronto che puoi installare e usare in un progetto.","also":["pacchetti","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Gestore di pacchetti","text":"Uno strumento che scarica e aggiorna i pacchetti da cui dipende il tuo codice. npm è uno dei più comuni.","also":["gestori di pacchetti","package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Lo strumento più usato per tenere la cronologia delle modifiche al codice, sotto forma di commit e branch."},{"id":"github","g":"build","word":"GitHub","text":"Un sito web che tiene i repository Git online, così i team condividono il codice, rivedono le modifiche e seguono il lavoro."},{"id":"vcs","g":"build","word":"Controllo di versione","text":"Conservare la cronologia completa di ogni modifica ai file, per vedere chi ha cambiato cosa e tornare indietro se serve. Lo fa Git.","also":["gestione delle versioni","version control","source control","version control system"]},{"id":"clone","g":"build","word":"Clonare","text":"Creare una tua copia completa di un repository, con la sua cronologia, sul tuo computer.","also":["clone","clonazione","clonato","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (scaricare le novità)","text":"Scaricare sul tuo computer gli ultimi commit dalla copia condivisa (come GitHub). L'opposto di push.","also":["git pull","scaricare","aggiornare"],"noTip":1},{"id":"mainbranch","g":"build","word":"Branch principale","text":"La versione ufficiale del codice da cui parte tutto il lavoro, spesso chiamata main o master.","also":["main","master","branch master","master branch","ramo principale"]},{"id":"conflict","g":"build","word":"Conflitto di merge","text":"Quando due modifiche toccano le stesse righe in modi diversi: il computer non riesce a unirle e una persona deve scegliere.","also":["conflitti di merge","conflitto di unione","merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (differenze)","text":"Una vista che mostra esattamente cosa è cambiato tra due versioni: le righe aggiunte e quelle tolte.","also":["diffs","differenze","confronto"]},{"id":"fork","g":"build","word":"Fork (copia personale)","text":"La tua copia del repository di qualcun altro, che puoi modificare senza toccare il suo.","also":["forks","forked","biforcazione","copia personale"]},{"id":"script","g":"build","word":"Script","text":"Un breve programma che fa un lavoro da solo, come mettere in ordine i file o avviare l'app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build (compilazione del progetto)","text":"Trasformare il codice in qualcosa di pronto da eseguire, oppure il risultato stesso, pronto da eseguire.","also":["builds","compilazione","costruire"],"noTip":1},{"id":"compile","g":"build","word":"Compilare","text":"Tradurre il codice scritto dalle persone in una forma che il computer può eseguire direttamente.","also":["compilazione","compilatore","compile","compiler"]},{"id":"cli","g":"build","word":"Riga di comando (CLI)","text":"Una finestra di testo in cui scrivi istruzioni per il computer invece di cliccare. Si dice anche terminale.","also":["riga di comando","terminale","console","command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configurazione (config)","text":"Le impostazioni che controllano come si comporta il software, tenute separate dal codice così sono facili da cambiare.","also":["config","configuration","impostazioni"],"noTip":1},{"id":"envvar","g":"build","word":"Variabile d'ambiente","text":"Un'impostazione data a un programma quando parte, spesso per indirizzi o password così non vengono scritti nel codice.","also":["variabili d'ambiente","env var","environment variable","environment variables"]},{"id":"debugging","g":"build","word":"Debug (ricerca degli errori)","text":"Cercare perché qualcosa non funziona, e correggerlo.","also":["debugging","fare il debug","debuggare","debug","debugged"]},{"id":"pairing","g":"build","word":"Programmazione in coppia","text":"Due persone (o una persona e un'IA) che lavorano insieme sullo stesso codice: una scrive e l'altra controlla.","also":["pair programming","pairing","coppia"]},{"id":"docs","g":"build","word":"Documentazione (docs)","text":"Spiegazioni scritte su come funziona qualcosa o su come usarlo.","also":["documentation","docs","doc"],"noTip":1},{"id":"readme","g":"build","word":"README (file «leggimi»)","text":"Il primo file da leggere in un repository: cos'è il progetto e come farlo partire.","also":["READMEs","leggimi","readme"]},{"id":"legacy","g":"build","word":"Sistema legacy (ereditato)","text":"Un vecchio sistema ancora in uso e difficile da cambiare, spesso perché poche persone lo capiscono ancora.","also":["sistemi legacy","codice legacy","legacy","legacy system","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Debito tecnico","text":"Scorciatoie che fanno risparmiare tempo adesso ma rendono più lenti i cambiamenti dopo, come un prestito su cui maturano gli interessi. Il refactoring serve a ripagarlo.","also":["tech debt","technical debt"]},{"id":"test","g":"test","word":"Test","text":"Un controllo che qualcosa funzioni come dovrebbe. Alcuni test li esegue il computer da solo a ogni modifica del codice; altri sei tu che provi una card finita prima di accettarla.","also":["testare","testi"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Abbreviazione di quality assurance (controllo qualità): tutto ciò che si fa per assicurarsi che il lavoro sia fatto bene prima che vada online. In AI-gile sono i controlli automatici: quando il QA è rosso, qualcosa è fallito e non può andare online finché non è sistemato.","also":["controlli di qualità","controllo qualità"]},{"id":"testpile","g":"test","word":"Pila di test","text":"Le card finite che aspettano di essere provate da te, una dopo l'altra. Accettane una o rimandala indietro con una nota, e arriva la successiva.","also":["pile di test"]},{"id":"autotest","g":"test","word":"Test automatico","text":"Un controllo che il computer esegue da solo a ogni modifica del codice, per scoprire presto gli errori.","also":["test automatici","test automatizzati","automated test","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Test manuale","text":"Una persona che prova il lavoro a mano per vedere se si comporta come dovrebbe.","also":["test manuali","manual test","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Test unitario","text":"Un piccolo controllo automatico di un minuscolo pezzo di codice preso da solo.","also":["test unitari","unit test","unit tests"]},{"id":"integtest","g":"test","word":"Test di integrazione","text":"Un controllo che verifica che più parti funzionino bene insieme, non solo una alla volta.","also":["test di integrazione","integration test","integration tests"]},{"id":"endtoend","g":"test","word":"Test end-to-end (E2E)","text":"Un test che si comporta come un utente vero dall'inizio alla fine, per esempio iscriversi, comprare e pagare.","also":["E2E","test end to end","end-to-end tests","test completo"]},{"id":"uat","g":"test","word":"Collaudo da parte dell'utente (UAT)","text":"Le persone che hanno chiesto il lavoro lo provano da sé e dicono se fa ciò di cui hanno bisogno. La pila di test di AI-gile ne è la versione.","also":["UAT","collaudo","test di accettazione","acceptance testing","user acceptance testing"]},{"id":"regression","g":"test","word":"Regressione","text":"Qualcosa che prima funzionava e si è rotto dopo una modifica. I test di regressione controllano che le cose vecchie funzionino ancora.","also":["regressioni","test di regressione","regression","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test (prova rapida)","text":"Un controllo velocissimo per vedere se le cose principali funzionano, per esempio subito dopo che una modifica va online. Se fallisce, ci si ferma a guardare.","also":["smoke tests","prova rapida","test del fumo"]},{"id":"exploratory","g":"test","word":"Test esplorativo","text":"Provare il prodotto liberamente e metterlo alla prova in modi diversi, per trovare problemi che i controlli pianificati non vedrebbero.","also":["test esplorativi","exploratory testing","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Caso di test","text":"Uno scenario scritto da provare: i passi, e cosa dovrebbe succedere.","also":["casi di test","scenario di test","test case","test cases"]},{"id":"coverage","g":"test","word":"Copertura dei test","text":"Quanta parte del codice è controllata da test automatici. Di solito di più è più sicuro, ma una copertura alta da sola non dimostra che funzioni bene.","also":["copertura del codice","test coverage","code coverage"]},{"id":"testdata","g":"test","word":"Dati di test","text":"Informazioni di esempio inventate, usate durante i test, così i dati privati di persone vere non vengono esposti.","also":["dati di prova","test data","test fixtures"]},{"id":"edgecase","g":"test","word":"Caso limite","text":"Una situazione insolita ai limiti, come un modulo vuoto o un nome con l'apostrofo, dove spesso le cose si rompono.","also":["casi limite","caso estremo","edge case","edge cases"]},{"id":"happypath","g":"test","word":"Percorso felice (happy path)","text":"Il percorso normale in cui tutto va bene. Testare bene significa provare anche i percorsi in cui qualcosa va storto."},{"id":"perftest","g":"test","word":"Test di prestazioni","text":"Controllare quanto è veloce qualcosa e come regge sotto sforzo.","also":["test di performance","performance testing","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Test di carico","text":"Controllare come se la cava un sistema quando tante persone lo usano insieme.","also":["test di carico","load testing","load test","load tests"]},{"id":"sectest","g":"test","word":"Test di sicurezza","text":"Cercare debolezze che potrebbero permettere a qualcuno di abusare di un sistema o di vedere ciò che non dovrebbe.","also":["test di sicurezza","security testing","security test","security tests"]},{"id":"accesstest","g":"test","word":"Test di accessibilità","text":"Controllare che persone con capacità diverse possano usare il prodotto, anche con uno screen reader o solo con la tastiera.","also":["test di accessibilità","accessibility testing","accessibility test"]},{"id":"linting","g":"test","word":"Linting (controllo dello stile)","text":"Un controllo automatico che individua probabili errori e stile disordinato nel codice, come un correttore ortografico per i programmi.","also":["linter","lint","linting","controllo dello stile"]},{"id":"static","g":"test","word":"Analisi statica","text":"Cercare problemi nel codice leggendolo in automatico, senza eseguirlo.","also":["analisi statica del codice","static analysis","static code analysis"]},{"id":"flaky","g":"test","word":"Test instabile (flaky)","text":"Un test che a volte passa e a volte fallisce senza una ragione chiara, per cui non ci si può fidare del tutto.","also":["test instabili","flaky test","flaky tests","test ballerino"]},{"id":"repro","g":"test","word":"Riprodurre (repro)","text":"Far ripresentare un bug apposta seguendo gli stessi passi, per poterlo studiare e correggere. Scrivere quei passi è la parte più utile di una segnalazione di bug.","also":["riproduzione","riproducibile","passi per riprodurre","repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Gravità","text":"Quanto è grave l'effetto di un problema, da un piccolo fastidio fino al blocco totale.","also":["livello di gravità","severità","severity","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Copiare una nuova versione del software sui computer che lo fanno funzionare, come una copia di prova o il servizio online."},{"id":"release","g":"change","word":"Rilascio","text":"Un insieme di lavoro finito, con un nome, che va online tutto insieme, con brevi note su cosa è cambiato. 🚀 Rilasci scrive le note partendo dalle card completate.","also":["rilasci","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Tornare all'ultima versione che funzionava quando una nuova causa guai. In AI-gile, ↩ Torna indietro raccoglie in un'unica checklist i passaggi per annullare scritti su ogni modifica.","also":["torna indietro","tornare indietro","roll back"]},{"id":"live","g":"change","word":"Online","text":"La versione vera che usano le persone, a differenza di una copia per fare prove. Gli sviluppatori la chiamano anche produzione.","also":["produzione","in produzione"],"noTip":1},{"id":"change","g":"change","word":"Modifica","text":"Una modifica pianificata a qualcosa su cui le persone contano, messa per iscritto prima: cosa, perché, il rischio, quando e come annullarla. Iniziane una con 🔀 Proponi una modifica.","also":["richiesta di modifica","richieste di modifica"],"noTip":1},{"id":"risk","g":"change","word":"Rischio","text":"Qualcosa che potrebbe andare storto, valutato in base a quanto è probabile e quanto sarebbe grave. ⚠️ Rischi li tiene in un'unica lista, dal punteggio più alto, ognuno con una data per riguardarlo.","also":["rischi","registro dei rischi"]},{"id":"chgwin","g":"change","word":"Finestra di modifica","text":"I momenti in cui le modifiche possono andare online, per esempio un tranquillo martedì sera. Fuori da una finestra una card di modifica non si può completare, a meno che non sia un'emergenza.","also":["finestre di modifica"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Un ultimo controllo subito prima che una modifica vada online: ogni persona che deve approvare dà il Via libera o dice Stop. Si va avanti solo se tutti danno il Via libera.","also":["go/no go","go-no-go","via libera"]},{"id":"approval","g":"change","word":"Approvazione","text":"Aspettare un sì prima che il lavoro inizi. Una card proposta da un amico, o una modifica, aspetta in ✅ Approvazioni finché non la approvi o la rifiuti.","also":["approvazioni"]},{"id":"quiettime","g":"change","word":"Orario di silenzio","text":"Un periodo, per esempio durante uno stream, una demo o la notte, in cui niente va online. I team continuano a lavorare e a testare, ma la messa online aspetta che finisca. Altrove si chiama blocco delle modifiche (change freeze).","also":["orari di silenzio","change freeze","congelamento delle modifiche"]},{"id":"devops","g":"change","word":"DevOps","text":"Un modo di lavorare in cui chi costruisce il software e chi lo fa funzionare sono un unico team, con molta automazione, così le modifiche vanno online spesso e in sicurezza."},{"id":"cicd","g":"change","word":"CI/CD (integrazione e consegna continue)","text":"Le modifiche di tutti vengono unite spesso nella versione principale e controllate in automatico ogni volta (integrazione continua), così il software è sempre pronto ad andare online con un clic (consegna continua).","also":["CI/CD","CI","CD","integrazione continua","consegna continua","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Rilascio continuo (continuous deployment)","text":"Un passo oltre la consegna continua: ogni modifica che supera i controlli va online da sola, senza nessun pulsante da premere.","also":["deployment continuo","continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (catena automatica)","text":"La serie automatica di passaggi che una modifica attraversa prima di andare online, come costruire, testare e poi rilasciare.","also":["pipelines","catena automatica","catena di integrazione"]},{"id":"environment","g":"change","word":"Ambiente","text":"Una copia separata del sistema per uno scopo, per esempio una per costruire, una per testare e quella online.","also":["ambienti","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Ambiente di sviluppo","text":"La copia in cui lavora uno sviluppatore, spesso sul proprio computer, dove rompere le cose non fa male a nessuno.","also":["ambiente di dev","dev environment","development environment"]},{"id":"testenv","g":"change","word":"Ambiente di test","text":"Una copia separata del sistema usata solo per i test, così il servizio vero non viene toccato.","also":["ambienti di test","test environment","test environments"]},{"id":"staging","g":"change","word":"Ambiente di staging (prova finale)","text":"Una copia configurata esattamente come quella online, per un ultimo controllo prima che una modifica vada online.","also":["staging","pre-produzione","ambiente di pre-produzione","staging environment"]},{"id":"artifact","g":"change","word":"Artefatto di build","text":"Il file o il pacchetto che una build produce, pronto per essere conservato, controllato o messo online.","also":["artefatti di build","artefatto","build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Correzione urgente (hotfix)","text":"Una correzione urgente messa online in fretta, fuori dal piano normale, perché qualcosa di importante è rotto.","also":["hotfix","hotfixes","correzione d'emergenza"]},{"id":"patch","g":"change","word":"Patch (correzione)","text":"Un piccolo aggiornamento che corregge un bug o chiude una falla di sicurezza. Applicare in fretta le patch di sicurezza è importante.","also":["patches","correzione","patch di sicurezza","security patch","security patches"]},{"id":"version","g":"change","word":"Numero di versione","text":"Un'etichetta come 2.4.1 che dice quale versione hai. Spesso il primo numero cambia per le modifiche grandi e l'ultimo per le piccole correzioni.","also":["numeri di versione","versionamento semantico","version number","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Note di rilascio","text":"Un breve elenco in parole semplici di cosa è cambiato in una versione, per chi la usa, comprese le correzioni e i limiti noti. Si dice anche changelog.","also":["registro delle modifiche","changelog","release notes","change log"]},{"id":"flag","g":"change","word":"Feature flag (interruttore di funzionalità)","text":"Un interruttore acceso/spento per una funzionalità, così il lavoro nuovo può andare online nascosto ed essere attivato (o disattivato) senza una nuova versione.","also":["feature flags","feature toggle","feature toggles","interruttore di funzionalità"]},{"id":"rollfwd","g":"change","word":"Correggere in avanti (roll forward)","text":"Rimediare a una versione difettosa pubblicando in fretta una nuova versione corretta, invece di tornare alla vecchia.","also":["roll forward","correzione in avanti","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Rilascio canarino (canary)","text":"Mettere online una modifica prima per un piccolo gruppo, e per tutti solo quando sembra andare bene. Il nome viene dai canarini che i minatori portavano sottoterra come segnale d'allarme.","also":["canary release","canary releases","canary","rilascio graduale"]},{"id":"bluegreen","g":"change","word":"Rilascio blue-green","text":"Tenere due copie del sistema online e spostare le persone sulla nuova tutte insieme, così puoi tornare subito indietro se va male.","also":["blue-green","blue green deployment","rilascio blu-verde","blu-verde"]},{"id":"zerodown","g":"change","word":"Rilascio senza interruzioni","text":"Mettere online una nuova versione senza che il servizio si fermi mai per i suoi utenti.","also":["zero downtime","zero-downtime","zero-downtime deployment","senza interruzioni"]},{"id":"chgenable","g":"change","word":"Gestione dei cambiamenti","text":"Aiutare i cambiamenti a riuscire: valutare il rischio, ottenere la giusta approvazione e scegliere il momento giusto. Si dice anche change management.","also":["change management","change enablement","gestione del cambiamento"]},{"id":"cab","g":"change","word":"Comitato per i cambiamenti (CAB)","text":"Un gruppo che esamina i cambiamenti importanti e decide se e quando possono andare avanti.","also":["CAB","comitato consultivo per i cambiamenti","change advisory board"]},{"id":"stdchange","g":"change","word":"Cambiamento standard","text":"Un cambiamento a basso rischio fatto ogni volta nello stesso modo collaudato, quindi approvato in anticipo.","also":["cambiamenti standard","standard change","standard changes"]},{"id":"normchange","g":"change","word":"Cambiamento normale","text":"Un cambiamento che va controllato e approvato prima di procedere.","also":["cambiamenti normali","normal change","normal changes"]},{"id":"emergchange","g":"change","word":"Cambiamento d'emergenza","text":"Un cambiamento che deve avvenire subito per riparare o evitare guai seri, e quindi con un'approvazione più rapida.","also":["cambiamenti d'emergenza","cambiamento urgente","emergency change","emergency changes"]},{"id":"automation","g":"change","word":"Automazione","text":"Far fare da solo al computer un lavoro ripetitivo, così è più veloce e viene fatto sempre allo stesso modo.","also":["automatizzare","automatizzato","automation","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruttura","text":"Le macchine, le reti e i servizi su cui gira il software.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Infrastruttura come codice (IaC)","text":"Descrivere i tuoi server e le loro impostazioni in file tenuti insieme al codice, così si possono ricostruire esattamente allo stesso modo ogni volta.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Cloud (nuvola)","text":"Affittare computer, spazio di archiviazione e servizi da un grande fornitore via internet, invece di possedere le macchine.","also":["il cloud","nuvola","cloud computing","the cloud"]},{"id":"provider","g":"change","word":"Fornitore cloud","text":"Un'azienda che affitta potenza di calcolo via internet, come Amazon Web Services (AWS), Microsoft Azure o Google Cloud.","also":["fornitori cloud","provider cloud","cloud provider","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting (spazio web)","text":"Il posto dove la tua app o il tuo sito risiede e funziona, così che le persone possano raggiungerlo, di solito affittato da un'azienda.","also":["hosting","ospitato"]},{"id":"domain","g":"change","word":"Nome di dominio","text":"L'indirizzo web che le persone digitano, come example.com. Lo affitti per un anno alla volta, quindi va rinnovato.","also":["nomi di dominio","dominio","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Abbreviazione di «sistema dei nomi di dominio»: la rubrica di internet, che trasforma un nome come example.com nell'indirizzo del computer giusto.","also":["sistema dei nomi di dominio","domain name system"]},{"id":"container","g":"change","word":"Container","text":"Un pacchetto sigillato che contiene un'app e tutto ciò di cui ha bisogno, così gira allo stesso modo su qualsiasi computer. Docker è lo strumento più noto.","also":["containers","contenitore","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Macchina virtuale (VM)","text":"Un computer finto che gira dentro uno vero, così una sola macchina potente può fare da tante.","also":["VM","VMs","macchine virtuali","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless (senza server)","text":"Eseguire codice senza occuparsi di nessun server: il fornitore lo fa girare quando serve e tu paghi quello che usi."},{"id":"lb","g":"change","word":"Bilanciatore di carico","text":"Qualcosa che distribuisce i visitatori su più server, così nessuno resta sovraccarico.","also":["bilanciatori di carico","load balancer","load balancers"]},{"id":"cache","g":"change","word":"Cache (memoria di appoggio)","text":"Una riserva di risultati recenti tenuta a portata di mano, così la stessa cosa non va recuperata o calcolata di nuovo. Svuotarla può sistemare pagine che sembrano non aggiornate.","also":["caches","caching","memorizzazione temporanea","cached"]},{"id":"cdn","g":"change","word":"Rete di distribuzione dei contenuti (CDN)","text":"Un insieme di server in tutto il mondo che tengono copie delle tue pagine e immagini vicino ai visitatori, così si caricano in fretta.","also":["CDN","rete di distribuzione","content delivery network"]},{"id":"migration","g":"change","word":"Migrazione","text":"Spostare dati o sistemi da una vecchia configurazione a una nuova, o cambiare con cura come è organizzato un database.","also":["migrazioni","migrazione del database","migration","migrations","database migration"]},{"id":"service","g":"run","word":"Servizio","text":"Qualcosa che hai costruito e su cui le persone contano, come un sito o un'app, curato perché continui a funzionare. Spunta «Questo progetto è un servizio» e indica cosa offre, chi lo usa e chi è reperibile.","also":["servizi"]},{"id":"uptimepct","g":"run","word":"Disponibilità (uptime)","text":"Quanta parte del tempo un servizio funziona, di solito in percentuale. Il 99,9% lascia comunque circa 43 minuti di fermo al mese.","also":["uptime","tempo di attività","percentuale di disponibilità","uptime percentage"]},{"id":"uptime","g":"run","word":"Controllo di uptime","text":"Un controllo automatico, ogni pochi minuti, che il tuo servizio risponda ancora. Se fallisce più volte di fila, AI-gile apre da solo una card di incidente.","also":["controlli di disponibilità","uptime checks"]},{"id":"statuspage","g":"run","word":"Pagina di stato","text":"Una pagina pubblica che mostra se un servizio funziona (verde, arancione o rosso) con l'ultimo aggiornamento, così chi lo usa può controllare invece di chiedere.","also":["pagine di stato","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Il punto in cui arrivano le domande e le segnalazioni di chi usa il tuo servizio. AI-gile smista ognuna in richiesta, incidente o idea, e lo dice quando somiglia a qualcosa già segnalato.","also":["help desk","helpdesk","assistenza"]},{"id":"svcrequest","g":"run","word":"Richiesta di servizio","text":"Qualcuno che chiede una cosa normale, come un nuovo account o un piccolo aiuto, invece di segnalare che qualcosa è rotto. Aspetta il suo turno: un incidente passa prima.","also":["richieste di servizio"]},{"id":"incident","g":"run","word":"Incidente","text":"Qualcosa che è rotto o non funziona bene per le persone che lo usano proprio adesso, come il sito web fermo o molto lento. Una card incidente 🔥 salta la fila: rimetterlo in funzione viene prima di tutto.","also":["incidenti"]},{"id":"major","g":"run","word":"Incidente grave","text":"Un incidente grosso: molte persone coinvolte, oppure soldi o dati a rischio. Un solo pulsante mette tutti i team al lavoro (sciame), sveglia chi è reperibile e chiede un aggiornamento di stato ogni 30 minuti.","also":["incidenti gravi"]},{"id":"oncall","g":"run","word":"Reperibilità","text":"Essere chi risponde quando qualcosa si rompe, anche di notte. Ogni servizio ha un membro del team reperibile, che viene svegliato per primo per i suoi incidenti.","also":["reperibile","reperibili","di guardia","on call"]},{"id":"replyby","g":"run","word":"Orario di risposta","text":"Quanto può aspettare una card prima di ricevere una prima risposta, per esempio un'ora per un incidente. Dopo compare un orologio rosso, così niente viene dimenticato in silenzio. Si chiama anche obiettivo di risposta.","also":["orari di risposta","obiettivo di risposta","obiettivi di risposta"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Un breve sguardo indietro dopo un incidente: cosa è successo, cosa ha aiutato e cosa cambiare, senza dare la colpa a nessuno. Un incidente non si può chiudere senza.","also":["postmortem","revisione post-incidente"]},{"id":"problem","g":"run","word":"Problema","text":"La causa nascosta dietro uno o più incidenti. Una card 🧩 problema raggruppa gli incidenti che continuano a tornare, così la causa viene trovata e risolta una volta per tutte.","also":["problemi"],"noTip":1},{"id":"rootcause","g":"run","word":"Causa radice","text":"Il vero motivo per cui qualcosa si è rotto, non solo quello che hai visto andare storto. Risolvi la causa radice e l'incidente smette di tornare.","also":["cause radice","causa principale"]},{"id":"workaround","g":"run","word":"Soluzione temporanea","text":"Un modo per far funzionare le cose finché la vera correzione non è pronta, come riavviare qualcosa quando si blocca. Viene scritta sulla card del problema, così nessuno deve scoprirla di nuovo.","also":["soluzioni temporanee","workaround"]},{"id":"knownerror","g":"run","word":"Errore noto","text":"Un problema di cui si conosce la causa ma che non è ancora risolto, di solito con una soluzione temporanea scritta. 🧩 Errori noti li elenca, così tutti usano la soluzione temporanea invece di indagare di nuovo.","also":["errori noti"]},{"id":"runbook","g":"run","word":"Runbook","text":"Istruzioni passo passo per risolvere un tipo di guaio già noto, così si fa sempre allo stesso modo, in fretta. Dopo un incidente grosso il team può proportene uno da approvare con un OK.","also":["manuale operativo","manuali operativi"]},{"id":"ci","g":"run","word":"Elemento di configurazione","text":"Una cosa da cui dipende il tuo servizio, come un server, un dominio, un certificato, una chiave o un fornitore. 🗂️ Elementi li elenca per servizio, così vedi cosa colpisce un incidente e cosa va rinnovato o ha bisogno di un backup.","also":["elementi di configurazione"]},{"id":"expiry","g":"run","word":"Scadenza","text":"La data dopo la quale qualcosa smette di funzionare se non viene rinnovato, come il certificato di sicurezza di un sito web o il suo indirizzo web. AI-gile tiene d'occhio queste date e crea una card per ogni rinnovo 30 giorni prima, così niente si ferma a sorpresa.","also":["scadenze","data di scadenza","date di scadenza","controllo delle scadenze"]},{"id":"backup","g":"run","word":"Backup","text":"Una copia salvata dei tuoi dati di prima, a cui ricorrere se qualcosa va perso o si danneggia. AI-gile fa ogni giorno un backup delle tue board.","also":["copia di sicurezza","copie di sicurezza"]},{"id":"restore","g":"run","word":"Ripristino","text":"Rimettere i dati da un backup. Un backup conta davvero solo quando sai che si può ripristinare, quindi vale la pena provarlo ogni tanto.","also":["ripristinare","ripristinato","ripristinata"]},{"id":"svcreview","g":"run","word":"Revisione del servizio","text":"Uno sguardo indietro su un mese di un servizio: incidenti aperti e risolti, quanto in fretta le persone hanno avuto una risposta, uptime e token usati. La Revisione mensile lo mostra per ogni servizio.","also":["revisioni del servizio","revisione mensile","revisioni mensili"]},{"id":"accessreview","g":"run","word":"Revisione accessi","text":"Controllare ogni 90 giorni chi può ancora entrare: link di condivisione, ruoli degli amici, password e chiavi salvate. Per ciascuno scegli se mantenerlo o rimuoverlo, così i vecchi accessi non restano in giro.","also":["revisioni accessi","revisione degli accessi"]},{"id":"improvements","g":"run","word":"Elenco dei miglioramenti","text":"Tutto ciò in cui il team ha deciso di migliorare, in un unico posto: suggerimenti delle retrospettive, azioni delle revisioni e correzioni dei problemi, ognuno con il suo stato. Lo trovi sotto 📈 Miglioramenti.","also":["elenchi dei miglioramenti","miglioramenti"]},{"id":"tokencap","g":"run","word":"Limite di token","text":"Un limite mensile ai token che gli agenti di un servizio possono usare. All'80% ricevi un avviso; al 100% il loro lavoro in background aspetta il mese dopo, o finché non alzi il limite.","also":["limiti di token","limite mensile di token"]},{"id":"svcmgmt","g":"run","word":"Gestione dei servizi","text":"Tutto ciò che serve a mantenere un servizio utile e funzionante per le persone che contano su di esso, giorno dopo giorno.","also":["gestire un servizio","service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Una guida molto usata alle buone pratiche di gestione dei servizi, che copre cose come incidenti, problemi e cambiamenti. In origine il nome era la sigla di IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Gestione dei servizi IT (ITSM)","text":"Gestire la tecnologia come un servizio per le persone, con modi chiari di trattare richieste, incidenti, cambiamenti e miglioramenti.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Servizio gestito","text":"Un servizio che qualcun altro fa funzionare e cura per te, con un accordo su quanto bene deve funzionare.","also":["servizi gestiti","managed service","managed services","servizio in gestione"]},{"id":"svcowner","g":"run","word":"Responsabile del servizio","text":"La persona che risponde di un servizio nel suo insieme: quanto bene funziona, quanto costa e come migliora.","also":["responsabili del servizio","proprietario del servizio","service owner","service owners"]},{"id":"sla","g":"run","word":"Accordo sul livello di servizio (SLA)","text":"Una promessa scritta ai clienti su quanto bene funzionerà un servizio, come «attivo il 99,9% del tempo» o «risposta entro un'ora», spesso con un rimborso se non viene rispettata.","also":["SLA","SLAs","accordi sul livello di servizio","service level agreement"]},{"id":"slo","g":"run","word":"Obiettivo di livello di servizio (SLO)","text":"L'obiettivo che il team si dà su quanto bene dovrebbe funzionare un servizio in un periodo, di solito un po' più severo dello SLA per sicurezza.","also":["SLO","SLOs","obiettivo di servizio"]},{"id":"sli","g":"run","word":"Indicatore di livello di servizio (SLI)","text":"La misura reale che confronti con un obiettivo, come la percentuale di visite in cui la pagina si è caricata correttamente.","also":["SLI","SLIs","indicatore di servizio"]},{"id":"availability","g":"run","word":"Disponibilità","text":"Se le persone possono usare un servizio quando ne hanno bisogno, spesso misurata come uptime.","also":["alta disponibilità","availability","high availability"]},{"id":"downtime","g":"run","word":"Fermo (downtime)","text":"Il tempo in cui un servizio non funziona o è spento, previsto o no.","also":["tempo di inattività","fermo del servizio","downtime","down time"]},{"id":"errorbudget","g":"run","word":"Budget di errore","text":"La piccola quantità di malfunzionamenti che il tuo obiettivo di affidabilità permette. Finché ne resta puoi rischiare con i cambiamenti; quando è esaurito, rallenti.","also":["budget di errori","error budget","error budgets"]},{"id":"outage","g":"run","word":"Interruzione di servizio","text":"Un periodo in cui un servizio è fermo o funziona gravemente male per i suoi utenti.","also":["interruzioni","guasto","blackout","outage","outages"]},{"id":"degraded","g":"run","word":"Servizio degradato","text":"Funziona, ma male: è lento, o alcune parti non funzionano.","also":["degradato","funzionamento ridotto","degraded","degraded service"]},{"id":"monitoring","g":"run","word":"Monitoraggio","text":"Sorvegliare un servizio in automatico, senza sosta, così i problemi vengono scoperti, idealmente prima che gli utenti se ne accorgano.","also":["monitoring","controllo continuo","monitorato"]},{"id":"observability","g":"run","word":"Osservabilità","text":"Quanto bene riesci a capire cosa succede dentro un sistema guardandolo da fuori, grazie ai suoi log, ai suoi numeri e alle sue tracce.","also":["o11y","observability"]},{"id":"log","g":"run","word":"Log (registro)","text":"Un diario che un programma tiene di ciò che sta facendo, usato per capire cosa è andato storto.","also":["logs","registro","registri","logging"],"noTip":1},{"id":"trace","g":"run","word":"Traccia (trace)","text":"Il resoconto di come una richiesta attraversa le diverse parti di un sistema, passo dopo passo, e mostra dove ha rallentato.","also":["tracce","traces","tracing","tracciamento"]},{"id":"latency","g":"run","word":"Latenza","text":"Quanto ci mette qualcosa a rispondere, come l'attesa tra il clic e la comparsa della pagina.","also":["tempo di risposta"]},{"id":"alert","g":"run","word":"Avviso (alert)","text":"Un messaggio automatico che dice che qualcosa richiede attenzione, per esempio il sito web che non risponde.","also":["avvisi","allarme","allarmi","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Stanchezza da avvisi","text":"Quando gli avvisi sono così tanti che le persone cominciano a ignorarli, compresi quelli importanti.","also":["alert fatigue","alarm fatigue","affaticamento da allarmi"]},{"id":"dashboard","g":"run","word":"Dashboard (cruscotto)","text":"Una schermata che mostra a colpo d'occhio i numeri e gli stati più importanti.","also":["dashboards","cruscotto","pannello di controllo"],"noTip":1},{"id":"paging","g":"run","word":"Chiamata di reperibilità (paging)","text":"Chiamare o svegliare con urgenza la persona di turno per un problema.","also":["paging","chiamare il reperibile","reperibilità","paged"]},{"id":"escalation","g":"run","word":"Escalation (passaggio al livello superiore)","text":"Coinvolgere qualcuno con più competenza o autorità quando un problema non si può risolvere al livello attuale, o non abbastanza in fretta.","also":["escalation","escalare","escalated","escalate","passaggio al livello superiore"]},{"id":"triage","g":"run","word":"Triage (smistamento)","text":"Ordinare rapidamente i problemi in arrivo in base a urgenza e importanza, così il peggiore viene gestito per primo.","also":["smistamento","triaged","fare il triage"]},{"id":"impact","g":"run","word":"Impatto","text":"Quanto qualcosa colpisce le persone: quante, e quanto gravemente.","noTip":1},{"id":"urgency","g":"run","word":"Urgenza","text":"Quanto in fretta va affrontata una cosa. Impatto e urgenza insieme stabiliscono la priorità.","noTip":1},{"id":"plevels","g":"run","word":"Livelli di priorità (P1, P2…)","text":"Etichette che dicono quanto è urgente un problema. P1 è il più grave e richiede di agire subito.","also":["P1","P2","P3","P4","livelli di priorità"]},{"id":"queue","g":"run","word":"Coda di ticket","text":"L'elenco delle richieste e degli incidenti in attesa di essere presi in carico.","also":["code di ticket","coda","ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Primo livello e secondo livello","text":"Livelli di assistenza: il primo livello risponde alla chiamata e risolve le cose semplici; il secondo ha competenze più approfondite per quelle difficili. Si dice anche livello 1 e livello 2.","also":["primo livello","secondo livello","supporto di primo livello","livello 1","livello 2","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Responsabile dell'incidente","text":"L'unica persona che guida la risposta a un incidente, così tutti sanno chi decide e chi fa cosa.","also":["incident commander","comandante dell'incidente","responsabili dell'incidente","incident commanders"]},{"id":"responsetime","g":"run","word":"Tempo di risposta","text":"Quanto passa prima che qualcuno prenda in carico per la prima volta una richiesta o un incidente.","also":["tempi di risposta","tempo di presa in carico","response time","response times"]},{"id":"resolution","g":"run","word":"Tempo di risoluzione","text":"Quanto ci vuole a sistemare del tutto una richiesta o un incidente, dalla segnalazione alla correzione.","also":["tempi di risoluzione","resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Tempo medio di ripristino (MTTR)","text":"In media, quanto ci vuole a far tornare a funzionare un servizio dopo un guasto. MTTR può voler dire cose leggermente diverse, quindi specifica cosa misuri.","also":["MTTR","tempo medio di riparazione","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Tempo medio tra i guasti (MTBF)","text":"In media, quanto a lungo un servizio funziona prima che qualcosa si rompa.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Database di gestione delle configurazioni (CMDB)","text":"L'elenco di tutti i tuoi elementi di configurazione e di come sono collegati, per vedere cosa dipende da cosa.","also":["CMDB","database delle configurazioni"]},{"id":"asset","g":"run","word":"Risorsa (asset)","text":"Qualsiasi cosa di valore che possiedi o paghi per far funzionare il servizio, come un portatile, una licenza software o un dominio.","also":["risorse","bene","beni","asset","assets","dotazione"],"noTip":1},{"id":"capplan","g":"run","word":"Pianificazione della capacità","text":"Assicurarsi che ci siano abbastanza potenza di calcolo, spazio e persone per ciò che sta arrivando.","also":["piano di capacità","capacity planning","capacity plan"]},{"id":"scaling","g":"run","word":"Scalare (scaling)","text":"Reggere più utenti dando più potenza a una macchina (scaling up) o aggiungendo più macchine (scaling out).","also":["scaling","scalabilità","ridimensionamento","scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Continuità operativa","text":"Piani per mantenere in piedi le cose importanti quando qualcosa di grosso va storto, come perdere un ufficio, un fornitore chiave o i computer.","also":["piano di continuità operativa","business continuity","business continuity plan","continuità aziendale"]},{"id":"dr","g":"run","word":"Ripristino in caso di disastro (DR)","text":"Il piano e gli strumenti per rimettere in piedi un servizio dopo qualcosa di grave, come la perdita di un intero centro dati.","also":["DR","disaster recovery","piano di ripristino","ripristino d'emergenza"]},{"id":"rto","g":"run","word":"Tempo massimo di ripristino (RTO)","text":"Il tempo massimo per cui un servizio può restare fermo dopo un disastro prima che debba funzionare di nuovo.","also":["RTO","obiettivo di tempo di ripristino","recovery time objective"]},{"id":"rpo","g":"run","word":"Perdita massima di dati accettabile (RPO)","text":"Quanti dati recenti puoi permetterti di perdere, misurato in tempo. Un RPO di un'ora significa backup almeno ogni ora.","also":["RPO","obiettivo del punto di ripristino","recovery point objective"]},{"id":"redundancy","g":"run","word":"Ridondanza","text":"Avere dei ricambi pronti, come un secondo server, così un guasto non ferma il servizio.","also":["ridondante","redundancy"]},{"id":"failover","g":"run","word":"Failover (passaggio al sistema di riserva)","text":"Il passaggio automatico a un sistema di riserva quando quello abituale si guasta.","also":["fail over","passaggio al sistema di riserva","commutazione automatica"]},{"id":"spof","g":"run","word":"Singolo punto di guasto","text":"Un elemento che si trascina dietro tutto quando si rompe, perché non c'è un ricambio.","also":["punti singoli di guasto","punto unico di guasto","SPOF","single point of failure","single points of failure"]},{"id":"maintwin","g":"run","word":"Finestra di manutenzione","text":"Un momento pianificato in cui un servizio può fermarsi o rallentare per la manutenzione, annunciato in anticipo agli utenti.","also":["finestre di manutenzione","manutenzione programmata","maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Passaggio di consegne","text":"Passare lavoro, conoscenze e responsabilità a un'altra persona o a un altro team, così niente va perso.","also":["passaggi di consegne","consegne","handover","handovers"]},{"id":"kb","g":"run","word":"Base di conoscenza","text":"Una raccolta di articoli di aiuto e di risposte, per gli utenti e per il team.","also":["basi di conoscenza","knowledge base","knowledge bases","archivio delle guide"]},{"id":"csat","g":"run","word":"Soddisfazione del cliente (CSAT)","text":"Un punteggio degli utenti che dice quanto sono stati contenti, spesso chiesto dopo la chiusura di una richiesta.","also":["CSAT","soddisfazione degli utenti","customer satisfaction"]},{"id":"supplier","g":"run","word":"Fornitore","text":"Un'azienda esterna su cui conti, come il tuo servizio di hosting. Si dice anche vendor o terza parte.","also":["fornitori","terza parte","terzi","supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Dismissione del servizio","text":"Spegnere un servizio per sempre, in sicurezza: avvisare i suoi utenti, occuparsi dei suoi dati e accessi, e fermare i suoi costi.","also":["dismettere un servizio","spegnere un servizio","service retirement","retiring a service"]},{"id":"eol","g":"run","word":"Fine vita (EOL)","text":"Quando un prodotto non riceve più aggiornamenti né assistenza dal suo produttore, quindi va sostituito.","also":["EOL","fine supporto","end of life","end-of-life"]},{"id":"cybersec","g":"sec","word":"Sicurezza informatica","text":"Proteggere sistemi e dati da intrusioni, furti e danni.","also":["cybersecurity","cybersicurezza","cyber security"]},{"id":"authn","g":"sec","word":"Autenticazione","text":"Verificare chi è qualcuno, di solito con una password o un codice. Spesso abbreviato in authn.","also":["authn","autenticarsi","authentication"]},{"id":"authz","g":"sec","word":"Autorizzazione","text":"Verificare cosa può fare qualcuno una volta che sai chi è. Spesso abbreviato in authz.","also":["authz","permessi di accesso","authorisation","authorization"]},{"id":"mfa","g":"sec","word":"Autenticazione a più fattori (MFA)","text":"Accedere con due o più prove, come una password più un codice sul telefono. Si dice anche autenticazione a due fattori (2FA).","also":["MFA","2FA","autenticazione a due fattori","verifica in due passaggi","doppia autenticazione","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Accesso unico (SSO)","text":"Accedere una volta sola per entrare in tanti sistemi, come usare ovunque il tuo account di lavoro.","also":["SSO","single sign-on","login unico"]},{"id":"pwmgr","g":"sec","word":"Gestore di password","text":"Un'app che crea password robuste e le ricorda per te.","also":["gestori di password","password manager","password managers","portachiavi di password"]},{"id":"secret","g":"sec","word":"Segreto (secret)","text":"Una password, una chiave o un altro codice privato che un programma usa per entrare in qualcosa. Non va mai condiviso né scritto nel codice.","also":["segreti","secret","secrets","credenziali segrete"],"noTip":1},{"id":"apikey","g":"sec","word":"Chiave API","text":"Un codice segreto che permette a un programma di usare l'API di un altro servizio, e mostra chi la usa (e la paga).","also":["chiavi API","API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Token di accesso","text":"Un pass temporaneo che dimostra che un programma può entrare, così non serve la tua password ogni volta. Non è la stessa cosa di un token di IA.","also":["token di accesso","gettone di accesso","access token","access tokens"]},{"id":"encryption","g":"sec","word":"Crittografia","text":"Codificare le informazioni in modo che solo chi ha la chiave giusta possa leggerle.","also":["cifratura","cifrato","crittografare","criptato","encryption","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Il modo sicuro in cui viaggiano le pagine web, mostrato dal lucchetto nel browser, così nessuno nel mezzo può leggerle o modificarle."},{"id":"cert","g":"sec","word":"Certificato SSL/TLS","text":"Una carta d'identità digitale che permette a un sito web di dimostrare chi è e di usare HTTPS. Scade, quindi va rinnovato.","also":["certificato TLS","certificato SSL","certificato","certificati","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permessi","text":"Le regole su chi può vedere o modificare cosa.","also":["permesso","autorizzazioni","permissions","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Privilegio minimo","text":"Dare a ogni persona o programma solo l'accesso di cui ha davvero bisogno, e solo per il tempo che serve.","also":["principio del privilegio minimo","least privilege","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Controllo degli accessi basato sui ruoli (RBAC)","text":"Dare l'accesso in base al ruolo, come lettore o redattore, invece che persona per persona.","also":["RBAC","accesso per ruoli","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerabilità","text":"Una debolezza che qualcuno potrebbe usare per entrare o fare danni.","also":["vulnerabilità","falla","falla di sicurezza","vulnerability","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day (falla sconosciuta)","text":"Una debolezza che gli attaccanti conoscono prima che i produttori abbiano avuto il tempo di correggerla.","also":["zero-days","zero day","falla zero-day","falla sconosciuta"]},{"id":"malware","g":"sec","word":"Malware","text":"Software dannoso, come i virus, fatto per danneggiare, spiare o rubare.","also":["software dannoso"]},{"id":"ransomware","g":"sec","word":"Ransomware (virus del riscatto)","text":"Un malware che blocca i tuoi file e chiede soldi per sbloccarli. Buoni backup sono la migliore difesa.","also":["ransomware attack","attacco ransomware","virus del riscatto"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Messaggi falsi che cercano di ingannarti per farti dare password o soldi, o aprire qualcosa di dannoso.","also":["email di phishing","e-mail di phishing","truffa via email","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Ingegneria sociale","text":"Ingannare le persone, invece dei computer, per ottenere un accesso, come una finta telefonata dall'«assistenza informatica»."},{"id":"firewall","g":"sec","word":"Firewall","text":"Una guardia che decide quale traffico di rete può entrare o uscire.","also":["firewalls","muro di protezione"]},{"id":"vpn","g":"sec","word":"VPN","text":"Abbreviazione di «rete privata virtuale»: un collegamento privato e cifrato su internet, spesso usato per raggiungere in sicurezza i sistemi di lavoro.","also":["rete privata virtuale","virtual private network"]},{"id":"ddos","g":"sec","word":"Negazione del servizio (DoS, DDoS)","text":"Inondare un servizio di così tanto traffico finto che le persone vere non riescono più a usarlo. DDoS vuol dire che arriva da tanti computer insieme.","also":["DoS","DDoS","negazione del servizio","attacco DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Test di intrusione (pen test)","text":"Ingaggiare esperti fidati perché provino a entrare, così le debolezze si trovano prima che le trovino veri attaccanti.","also":["pen test","pentest","test di penetrazione","pen testing","penetration testing","penetration test"]},{"id":"audit","g":"sec","word":"Audit di sicurezza","text":"Un controllo accurato di quanto bene è protetto qualcosa, rispetto a un elenco di buone pratiche.","also":["audit di sicurezza","verifica di sicurezza","security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Modellazione delle minacce","text":"Pensare a chi potrebbe attaccare qualcosa, come, e cosa faresti per fermarlo.","also":["modello delle minacce","analisi delle minacce","threat modelling","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Violazione dei dati (data breach)","text":"Quando informazioni private finiscono a chi non dovrebbe averle, o vengono perse o cambiate senza permesso.","also":["violazioni dei dati","fuga di dati","data breach","data breaches"]},{"id":"pii","g":"sec","word":"Dati personali","text":"Qualsiasi informazione su una persona che può essere identificata, come un nome, un indirizzo email o un luogo. In inglese si dice anche PII.","also":["dato personale","PII","informazioni personali","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"La legge europea sui dati personali (il Regno Unito ne ha una sua versione): raccogli solo ciò che ti serve, tienilo al sicuro, e lascia che le persone vedano o cancellino i propri.","also":["regolamento generale sulla protezione dei dati","RGPD","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Protezione dei dati","text":"Prendersi cura dei dati personali come si deve e nel rispetto della legge.","also":["legge sulla protezione dei dati","data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Informativa sulla privacy","text":"Una pagina pubblica che dice quali dati personali raccogli, perché, e cosa ne fai.","also":["privacy policy","politica sulla privacy","dichiarazione sulla privacy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consenso","text":"Il sì chiaro e libero di una persona a che i suoi dati vengano usati in un certo modo. Può ritirarlo in qualsiasi momento.","also":["opt-in","accordo","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Un piccolo file che un sito web salva nel tuo browser per ricordare cose, come il fatto che hai effettuato l'accesso. Alcuni richiedono prima il tuo consenso.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimizzazione dei dati","text":"Raccogliere e conservare solo i dati personali di cui hai davvero bisogno per il lavoro.","also":["limitazione dei dati","data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Conservazione dei dati","text":"Per quanto tempo i dati vengono conservati prima di essere cancellati. Non tenerli più del necessario è più sicuro e spesso richiesto dalla legge.","also":["periodo di conservazione","data retention","retention period"]},{"id":"anon","g":"sec","word":"Anonimizzazione","text":"Modificare i dati in modo che non si possa più, ragionevolmente, risalire a nessuno.","also":["anonimizzato","dati anonimi","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonimizzazione","text":"Sostituire nomi e altri dettagli con codici, con una chiave tenuta a parte per ricollegarli. Restano comunque dati personali.","also":["pseudonimizzato","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Accordo sul trattamento dei dati (DPA)","text":"Un contratto che dice come un fornitore può trattare dati personali per tuo conto.","also":["DPA","contratto di trattamento dei dati","data processing agreement"]},{"id":"dpia","g":"sec","word":"Valutazione d'impatto sulla protezione dei dati (DPIA)","text":"Un esame attento, prima di cominciare, di come un progetto che usa dati personali potrebbe avere effetti sulle persone e di come ridurre i rischi.","also":["DPIA","valutazione d'impatto","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Registro di audit","text":"Un registro di chi ha fatto cosa e quando, così le azioni si possono controllare dopo.","also":["registri di audit","traccia di audit","audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Conformità","text":"Rispettare le leggi, le regole e gli standard che ti riguardano, ed essere in grado di dimostrare che lo fai.","also":["conforme","compliance","compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Uno standard internazionale molto noto per gestire la sicurezza delle informazioni. Le aziende possono farsi certificare secondo questo standard.","also":["ISO/IEC 27001","norma ISO 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Un rapporto americano, verificato da revisori esterni, che mostra che un'azienda si prende cura come si deve dei dati dei clienti.","also":["SOC2","report SOC 2"]},{"id":"agent","g":"ai","word":"Agente","text":"Un'IA che lavora da sola su un compito: legge il codice, fa modifiche, esegue controlli e riferisce. Il suo lavoro viene comunque controllato.","also":["agenti"]},{"id":"token","g":"ai","word":"Token","text":"I piccoli pezzi di testo che un'IA legge e scrive, circa tre quarti di parola ciascuno. L'uso dell'IA si conta in token: meno token usi, più piano ti resta.","also":["Token"]},{"id":"hook","g":"ai","word":"Hook","text":"Un piccolo comando che parte da solo in un momento preciso, per esempio quando inizia una sessione di IA, così il team sente i tuoi commenti.","also":["Hook"]},{"id":"ai","g":"ai","word":"Intelligenza artificiale (IA)","text":"Sistemi informatici che fanno cose che di solito pensiamo richiedano una persona, come scrivere, rispondere a domande o riconoscere immagini.","also":["IA","AI","intelligenza artificiale","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Apprendimento automatico (ML)","text":"Un modo per far imparare ai computer degli schemi da tanti esempi, invece di dare loro regole precise.","also":["machine learning","ML","apprendimento automatico"]},{"id":"model","g":"ai","word":"Modello","text":"Il «cervello» addestrato di un sistema di IA, costruito imparando da un enorme numero di esempi. I modelli differiscono per abilità, velocità e prezzo.","also":["modelli","modello di IA","model","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Modello linguistico di grandi dimensioni (LLM)","text":"Un modello di IA addestrato su enormi quantità di testo, così sa leggere e scrivere testi.","also":["LLM","LLMs","modello linguistico","large language model"]},{"id":"genai","g":"ai","word":"IA generativa","text":"Un'IA che crea cose nuove, come testo, immagini o codice, invece di limitarsi a classificarle o riconoscerle.","also":["GenAI","IA generativa","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Un programma con cui parli nel linguaggio di tutti i giorni, scrivendo o parlando.","also":["chatbots","assistente virtuale","bot conversazionale"]},{"id":"prompt","g":"ai","word":"Prompt (istruzione)","text":"Ciò che dai a un'IA: la tua domanda o le tue istruzioni, più tutto quello che le passi. Prompt più chiari di solito danno risposte migliori.","also":["prompts","istruzione","richiesta","comando"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"L'abilità di scrivere prompt che danno risultati affidabili e utili.","also":["scrittura di prompt","ingegneria dei prompt"]},{"id":"sysprompt","g":"ai","word":"Prompt di sistema","text":"Istruzioni di fondo che un'IA riceve prima che la conversazione inizi e che ne fissano il ruolo e le regole. Pesano più di ciò che scrivi tu.","also":["prompt di sistema","istruzioni di sistema","system prompt","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Contesto","text":"Tutto ciò che l'IA può vedere mentre lavora: le istruzioni, i tuoi messaggi, i file che ha letto e le risposte precedenti.","noTip":1},{"id":"ctxwin","g":"ai","word":"Finestra di contesto","text":"Quanto un'IA riesce a tenere a mente in una volta, misurato in token. Oltre quel limite, le parti più vecchie vengono scartate o riassunte.","also":["finestre di contesto","context window","context windows"]},{"id":"session","g":"ai","word":"Sessione","text":"Una conversazione di lavoro con un'IA, dall'inizio alla fine. Una nuova sessione parte con la memoria pulita.","also":["sessioni","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memoria","text":"Appunti che un'IA conserva tra una sessione e l'altra, così ricorda le tue preferenze e le decisioni passate.","noTip":1},{"id":"hallucination","g":"ai","word":"Allucinazione","text":"Quando un'IA dice con sicurezza qualcosa che è inventato o sbagliato. Controlla i fatti importanti.","also":["allucinazioni","allucinare","hallucination","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Addestramento","text":"Insegnare a un modello mostrandogli un numero enorme di esempi, prima che qualcuno lo usi.","also":["addestrato","training","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Dati di addestramento","text":"Gli esempi da cui un modello ha imparato. Le sue conoscenze si fermano alla data in cui quei dati sono stati raccolti.","also":["insieme di addestramento","training data","training set"]},{"id":"cutoff","g":"ai","word":"Data limite delle conoscenze","text":"La data in cui finiscono le conoscenze integrate di un'IA. Non saprà nulla di ciò che è successo dopo, a meno che non vada a cercarlo.","also":["knowledge cutoff","data di taglio","training cutoff"]},{"id":"finetune","g":"ai","word":"Affinamento (fine-tuning)","text":"Un addestramento extra di un modello esistente sui tuoi esempi, per renderlo più bravo in un lavoro preciso.","also":["fine-tuning","ottimizzazione","finetune","fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inferenza","text":"Un modello di IA mentre viene davvero usato per rispondere a qualcosa, e non mentre viene addestrato.","also":["inference","inferenza del modello","model inference"]},{"id":"tooluse","g":"ai","word":"Uso di strumenti","text":"Un'IA che può fare cose, non solo parlare: eseguire comandi, leggere file o cercare sul web, tramite gli strumenti che l'app le dà.","also":["chiamata di strumenti","chiamate di strumenti","tool use","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Sotto-agente","text":"Un'IA ausiliaria a cui un'IA principale affida un lavoro più piccolo e da cui riceve il risultato.","also":["sotto-agenti","subagent","subagents","sub-agent","subagente"]},{"id":"multiagent","g":"ai","word":"Multi-agente","text":"Più IA che lavorano insieme su uno stesso lavoro, ciascuna con la sua parte, come un piccolo team.","also":["sistema multi-agente","multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomia","text":"Quanto un'IA può fare da sola prima di dover chiedere a una persona.","also":["autonomo","autonomy","autonomous"]},{"id":"hitl","g":"ai","word":"Umano nel ciclo (human in the loop)","text":"Tenere coinvolta una persona per controllare o approvare ciò che fa l'IA nei punti chiave. In AI-gile sei tu.","also":["human in the loop","human-in-the-loop","HITL","supervisione umana"]},{"id":"guardrails","g":"ai","word":"Guardrail (protezioni)","text":"Limiti e controlli che mantengono sicure le azioni di un'IA, come richiedere l'approvazione prima che qualcosa vada online. Riducono il rischio di errori, ma non li escludono.","also":["guardrails","guardrail","protezioni","barriere di sicurezza"]},{"id":"rag","g":"ai","word":"Generazione aumentata dal recupero (RAG)","text":"Lasciare che un'IA cerchi nei tuoi documenti prima di rispondere, così le sue risposte si basano sulle tue informazioni.","also":["RAG","retrieval-augmented generation","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (rappresentazione numerica)","text":"Trasformare un testo in un elenco di numeri che ne cattura il significato, così un computer può trovare cose dal significato simile.","also":["embeddings","rappresentazione vettoriale","rappresentazione numerica"]},{"id":"vectordb","g":"ai","word":"Database vettoriale","text":"Un database fatto per cercare in quegli elenchi di numeri (gli embedding), per trovare contenuti di significato simile.","also":["database vettoriali","vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Un modo standard di collegare strumenti e fonti di dati alle app di IA, così un'IA può usarli.","also":["MCP","protocollo di contesto del modello"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Un'impostazione che dice quanto sono audaci le risposte di un'IA. Bassa dà risposte più stabili e prevedibili; alta, risposte più varie. In nessuno dei due casi avrà sempre ragione.","also":["temperatura del modello","temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodale","text":"Capace di lavorare con più di un tipo di informazione, come testo, immagini e suoni.","also":["multi-modale","multimodal"]},{"id":"evals","g":"ai","word":"Valutazione (eval)","text":"Un test pianificato di quanto bene se la cava un'IA su esempi scelti, per confrontare modelli o prompt.","also":["eval","evals","valutazioni"]},{"id":"bias","g":"ai","word":"Pregiudizio (bias)","text":"Quando un'IA (o una persona) è sbilanciata ingiustamente da una parte, spesso a causa di ciò da cui ha imparato.","also":["bias","distorsione","di parte","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"IA responsabile","text":"Usare l'IA in modo giusto, sicuro e onesto, con le persone che restano responsabili dei risultati.","also":["IA etica","responsible AI","ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection (iniezione di istruzioni)","text":"Un trucco in cui istruzioni nascoste in una pagina web o in un file cercano di far fare a un'IA qualcosa che il suo utente non ha chiesto.","also":["prompt injections","iniezione di prompt","iniezione di istruzioni"]},{"id":"ratelimit","g":"ai","word":"Limite di frequenza (rate limit)","text":"Un tetto al numero di richieste che puoi mandare a un servizio in un dato tempo. Se lo superi, devi aspettare.","also":["rate limit","rate limits","rate limited","limiti di frequenza","limite di richieste"]},{"id":"usagelimit","g":"ai","word":"Limite di utilizzo","text":"Quanto lavoro di IA consente il tuo piano in un certo periodo; superato quel limite, si ferma o costa di più.","also":["limiti di utilizzo","quota","usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Costruire software descrivendo per lo più a un'IA ciò che vuoi e lasciando che scriva il codice.","also":["vibe-coding","programmare a sensazione"]},{"id":"budget","g":"money","word":"Budget","text":"La somma di denaro messa da parte per qualcosa.","also":["budgets","bilancio previsto"],"noTip":1},{"id":"costest","g":"money","word":"Stima dei costi","text":"La migliore previsione possibile di quanto costerà qualcosa, fatta prima di iniziare.","also":["stime dei costi","preventivo","cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Ritorno sull'investimento (ROI)","text":"Quello che ottieni rispetto a quello che hai investito. Se è positivo, ne è valsa la pena.","also":["ROI","ritorno sull'investimento","return on investment"]},{"id":"tco","g":"money","word":"Costo totale di proprietà (TCO)","text":"Tutto ciò che una cosa costa davvero in tutta la sua vita, non solo il prezzo d'acquisto: gestione, assistenza, aggiornamenti e infine la dismissione.","also":["TCO","costo totale","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx e OpEx (spese di investimento e di esercizio)","text":"CapEx sono i soldi spesi in anticipo per cose che tieni; OpEx è la spesa continua, come le bollette mensili.","also":["CapEx","OpEx","spese di investimento","spese di esercizio","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Abbonamento","text":"Pagare regolarmente, di solito ogni mese o ogni anno, per continuare a usare qualcosa.","also":["abbonamenti","subscription","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software come servizio (SaaS)","text":"Software che usi online e paghi con un abbonamento, mentre chi lo ha creato lo fa funzionare per te.","also":["SaaS","software online","software as a service"]},{"id":"payg","g":"money","word":"Pagamento a consumo","text":"Pagare solo ciò che usi, come il cloud computing o i token di IA.","also":["pay as you go","pay-as-you-go","a consumo","tariffa a consumo","usage-based pricing"]},{"id":"overage","g":"money","word":"Consumo oltre il piano (overage)","text":"Un uso superiore a quello incluso nel tuo piano, che può costare un extra.","also":["overage","overages","costi extra","overage charges","eccedenza"]},{"id":"billingalert","g":"money","word":"Avviso di fatturazione","text":"Un messaggio quando la spesa o l'uso raggiunge un livello che hai scelto. Ti avvisa, ma non sempre ferma altri addebiti.","also":["avvisi di fatturazione","avviso di spesa","billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Piano gratuito","text":"Un livello gratuito di un servizio a pagamento, con dei limiti. Comodo per cominciare.","also":["livello gratuito","versione gratuita","free tier","free plan"]},{"id":"pricing","g":"money","word":"Piano tariffario","text":"I diversi pacchetti che un servizio vende, ognuno con il suo prezzo e i suoi limiti.","also":["piani tariffari","listino","piani","pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licenza","text":"Le regole su come puoi usare, copiare, modificare o condividere qualcosa fatto da altri, come software, caratteri o immagini.","also":["licenze","licence","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source (codice aperto)","text":"Software il cui codice può essere letto da chiunque, usato e spesso modificato gratis, secondo le regole della sua licenza.","also":["open-source","codice aperto","software libero","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Licenza open source","text":"Le regole che accompagnano il codice open source. Alcune permettono quasi tutto (come MIT); altre chiedono di condividere anche le tue modifiche (come GPL).","also":["licenze open source","licenza libera","licenza MIT","GPL","open source licence","open source licences","MIT licence"]},{"id":"proprietary","g":"money","word":"Proprietario","text":"Di proprietà di un'azienda e non libero da copiare o modificare. L'opposto di open source.","also":["software proprietario","proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Diritto d'autore","text":"Il diritto legale di chi crea di controllare le copie della propria opera, compresi codice e testi.","also":["copyright","protetto da copyright","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Proprietà intellettuale (PI)","text":"Idee e creazioni che la legge considera di proprietà di qualcuno, come codice, design, nomi e loghi.","also":["PI","IP","proprietà intellettuale","intellectual property"]},{"id":"tos","g":"money","word":"Termini di servizio","text":"Le regole che accetti quando usi un servizio.","also":["termini e condizioni","condizioni d'uso","terms of service","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contratto","text":"Un accordo scritto tra due parti che la legge farà rispettare.","also":["contratti","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Capitolato (SOW)","text":"Un documento che stabilisce esattamente quale lavoro sarà fatto, per quando e per quanto.","also":["SOW","descrizione dei lavori","statement of work"]},{"id":"fixedprice","g":"money","word":"Prezzo fisso","text":"Un prezzo concordato per tutto il lavoro, a prescindere da quanto tempo ci voglia.","also":["a corpo","prezzo a forfait","forfait","fixed price","fixed-price"]},{"id":"tm","g":"money","word":"A tempo e materiali","text":"Pagare le ore davvero lavorate e le cose davvero usate, invece di un prezzo fissato.","also":["T&M","a ore","time and materials","tempo e materiali"]},{"id":"invoice","g":"money","word":"Fattura","text":"Un conto che chiede il pagamento di un lavoro fatto o di beni forniti.","also":["fatture","invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Dipendenza dal fornitore (lock-in)","text":"Quando cambiare fornitore è così difficile o costoso che non puoi più fare a meno di lui.","also":["lock-in","vendor lock-in","vincolo con il fornitore","lock in"]},{"id":"procurement","g":"money","word":"Acquisti (procurement)","text":"Il processo di scegliere i fornitori e comprare da loro.","also":["approvvigionamento","procurement","appalti"]},{"id":"servicecredit","g":"money","word":"Credito di servizio","text":"Denaro restituito o uno sconto che ottieni quando un fornitore non rispetta il suo SLA.","also":["crediti di servizio","penale SLA","service credit","service credits"]}]}};
